"""
Workspace-aware ReAct loop.

The kernel:
  - Loads a workspace (agent.yaml + prompts + tool descriptions + extras).
  - Runs a ReAct loop with a budget (max_turns).
  - Dispatches tool calls: built-in (web_search/read_url)
    OR workspace-provided (workspace/tools/<name>.py).
  - Runs middleware hooks around each LLM turn and each tool call.

Built-in tool implementations live here; new tools are added by the proposer
in the workspace, NOT by editing this file.
"""

from __future__ import annotations

import asyncio
import copy
import json
import logging
import re
import time
import uuid
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from types import SimpleNamespace
from typing import Any

from . import llm, reader
from . import web_config as web_settings
from . import workspace as ws_mod
from .tool_result import ToolResult, format_tool_observation
from .tools import web_search_structured
from .trace import TraceWriter
from .workspace import WorkspaceBundle

logger = logging.getLogger(__name__)


# ---------------------------------------------------------------------------
# Final-answer guard: reject turns whose text is really unexecuted tool-call
# markup rather than a plain final answer.
# ---------------------------------------------------------------------------

_TOOL_CALL_MARKUP_RE = re.compile(
    r"<\s*(?:"
    r"\|?DSML\|?\s*(?:tool_calls?|invoke|function_calls?)\b"
    r"|invoke\b"
    r"|function_calls?\b"
    r"|tool_calls?\b"
    r"|antml:invoke\b"
    r")",
    re.IGNORECASE,
)

_LEGACY_TOOL_CALL_MARKUP_RES = (
    re.compile(r"\bfunction_call\s*[:(=]", re.IGNORECASE),
    re.compile(r"""[\'"]function_call[\'"]\s*:\s*\{""", re.IGNORECASE),
    re.compile(r"\btool_calls?\s*:\s*[\[{]", re.IGNORECASE),
    re.compile(r"""[\'"]tool_calls?[\'"]\s*:\s*[\[{]""", re.IGNORECASE),
)


def _contains_unexecuted_tool_call_markup(text: str) -> bool:
    """Return True when *text* looks like tool-call syntax, not a final answer."""
    if not text:
        return False
    # DeepSeek DSML uses the fullwidth vertical bar (U+FF5C); normalize it so
    # one regex can handle both <DSML ...> and <｜DSML｜...> spellings.
    normalized = text.replace("｜", "|")
    if _TOOL_CALL_MARKUP_RE.search(normalized):
        return True
    return any(pattern.search(text) for pattern in _LEGACY_TOOL_CALL_MARKUP_RES)


# ---------------------------------------------------------------------------
# Runtime context — passed to middleware hooks and workspace tools
# ---------------------------------------------------------------------------


@dataclass
class SearchRecord:
    idx: int
    query: str
    turn: int
    items: list
    urls: list


@dataclass
class ReadRecord:
    idx: int
    url: str
    focus: str
    turn: int
    success: bool
    failure_type: str | None
    artifact_path: str | None
    content_preview: str


@dataclass
class ToolCallRecord:
    seq: int
    requested_name: str
    requested_args: dict
    executed_name: str
    executed_args: dict
    turn: int
    result_preview: str
    result_metadata: dict = field(default_factory=dict)
    action: str = "executed"
    source: str = "model"


@dataclass
class Context:
    workspace: WorkspaceBundle
    trace: TraceWriter
    working_dir: Path = field(default_factory=Path.cwd)
    # ── identity / config ──
    question: str = ""
    run_id: str = ""
    run_dir: str = ""
    model: str = ""
    max_turns: int = 0
    # ── counters ──
    search_calls: int = 0
    read_calls: int = 0
    # ── structured history ──
    searches: list = field(default_factory=list)
    reads: list = field(default_factory=list)
    tool_history: list = field(default_factory=list)
    current_turn_calls: list = field(default_factory=list)
    # ── middleware state ──
    sub_agents: dict[str, Any] = field(default_factory=dict)
    state: dict = field(default_factory=lambda: defaultdict(dict))
    memory: list = field(default_factory=list)
    # ── internal ──
    _current_turn: int = 0
    _tool_seq: int = 0
    _side_llm_calls: int = 0
    _side_llm_max: int = 20
    _in_injected_call: bool = False
    _pending_injections: list = field(default_factory=list)
    _tool_skips: int = 0
    _tool_redirects: int = 0
    _injections_count: int = 0
    _final_continues: int = 0
    _final_continue_max: int = 3
    # ── tool execution budget / finalization / stall detection ──
    max_tool_calls: int = 0
    _completion_tool: str = ""
    _completion_tool_called: bool = False
    _length_retry_used: bool = False
    _stall_signature_counts: dict = field(default_factory=lambda: defaultdict(int))
    _last_tool_signature: str = ""
    _introspection_streak: int = 0
    _stall_nudges: int = 0
    _stall_nudge_pending: str = ""
    # ── context management ──
    _prereq_supervisor_credentials: bool = False
    _prereq_app_logins: dict[str, str] = field(default_factory=dict)
    model_usage: list = field(default_factory=list)

    @property
    def turn(self) -> int:
        return self._current_turn

    @property
    def elapsed_s(self) -> float:
        return round(time.time() - self.trace._t0, 1)

    @property
    def remaining_turns(self) -> int:
        return max(0, self.max_turns - self._current_turn)

    @property
    def tool_calls_executed(self) -> int:
        return self._tool_seq

    @property
    def remaining_tool_calls(self) -> int:
        if self.max_tool_calls <= 0:
            return max(0, (self.max_turns * 2) - self._tool_seq)
        return max(0, self.max_tool_calls - self._tool_seq)

    async def side_text(
        self, prompt: str, *, purpose: str, max_tokens: int = 500
    ) -> str | None:
        if self._side_llm_calls >= self._side_llm_max:
            self.trace.event("side_llm_budget_exceeded", budget=self._side_llm_max)
            return None
        self._side_llm_calls += 1
        capped = min(max_tokens, 500)
        started = time.monotonic()
        try:
            result, response = await llm.text(
                prompt,
                model=llm.SIDE_MODEL,
                max_tokens=capped,
                _return_response=True,
            )
        except Exception as e:
            self.trace.event(
                "side_llm_error",
                call_n=self._side_llm_calls,
                purpose=purpose,
                error=str(e),
            )
            return None
        self.trace.event(
            "side_llm",
            call_n=self._side_llm_calls,
            purpose=purpose,
            prompt_len=len(prompt),
            result_len=len(result),
        )
        usage = {
            "role": "side",
            "call_n": self._side_llm_calls,
            "model": llm.SIDE_MODEL,
            "call_id": getattr(response, "id", None),
            "latency_seconds": time.monotonic() - started,
            "usage": llm.usage_dict(response),
        }
        self.model_usage.append(usage)
        self.trace.event("model_usage", **usage)
        return result


# ---------------------------------------------------------------------------
# Persistent runtime context line
# ---------------------------------------------------------------------------

_COMPLETION_TOOL_CANDIDATES = ("supervisor.complete_task", "complete_task")

# AppWorld-style execution tools expose supervisor and app APIs inside Python code
# rather than as separate runtime tools. Detect those calls from the submitted
# code/result so the persistent status line can still track the real terminal and
# authentication prerequisites.
_APP_LOGIN_RE = re.compile(r"\b([A-Za-z_]\w*)\s*\.\s*login\s*\(", re.IGNORECASE)
_SUPERVISOR_CREDENTIAL_RE = re.compile(
    r"\b(?:supervisor\s*\.\s*(?:get_credentials|get_app_credentials|"
    r"list_credentials|get_credential|get_secret)\s*\(|"
    r"get_supervisor_credentials\s*\(|supervisor\s*\.\s*credentials\b)",
    re.IGNORECASE,
)
_COMPLETION_CALL_RE = re.compile(
    r"\b(?:supervisor\s*\.\s*complete_task|complete_task)\s*\(",
    re.IGNORECASE,
)
_LOGIN_FAILURE_RE = re.compile(
    r"\b(?:failed?|failure|incorrect|invalid|denied|unauthorized|"
    r"traceback|exception|wrong\s+password)\b",
    re.IGNORECASE,
)


def _result_indicates_task_completed(result: str) -> bool:
    """Best-effort detection of an AppWorld task_completed flag."""
    if not result:
        return False
    try:
        data = json.loads(result)
    except (json.JSONDecodeError, TypeError):
        data = None
    if isinstance(data, dict) and data.get("task_completed") is True:
        return True
    return bool(re.search(r"\btask_completed\s*[:=]\s*true\b", result, re.IGNORECASE))


def _result_indicates_failure(result: str) -> bool:
    """Best-effort failure detection for AppWorld tool output strings.

    JSON keys named ``error`` are common even on success (e.g. ``{"error": null}``),
    so the JSON case is inspected first and the bare key is intentionally not
    treated as a failure.
    """
    if not result:
        return False
    try:
        data = json.loads(result)
    except (json.JSONDecodeError, TypeError):
        data = None
    if isinstance(data, dict):
        err = data.get("error") or data.get("exception")
        if (isinstance(err, str) and err.strip()) or err:
            return True
        if data.get("success") is False:
            return True
        output = data.get("output")
        if isinstance(output, str) and _LOGIN_FAILURE_RE.search(output):
            return True
    return bool(_LOGIN_FAILURE_RE.search(result))


def _detect_completion_tool(ctx: Context) -> str | None:
    """Return the workspace terminal-completion tool name, if present."""
    tool_names = list(getattr(ctx.workspace, "tool_names", None) or [])
    for candidate in _COMPLETION_TOOL_CANDIDATES:
        if candidate in tool_names:
            return candidate
    for name in tool_names:
        if name.endswith("complete_task"):
            return name
    return None


def _is_appworld_environment(ctx: Context) -> bool:
    """True when the workspace exposes AppWorld-style execute/supervisor APIs."""
    for name in getattr(ctx.workspace, "tool_names", None) or []:
        lowered_name = name.lower()
        if "appworld" in lowered_name or "app_world" in lowered_name or "app world" in lowered_name:
            return True
    for schema in getattr(ctx.workspace, "tool_schemas", None) or []:
        if not isinstance(schema, dict):
            continue
        desc = (schema.get("function") or {}).get("description", "") or ""
        lowered = desc.lower()
        if "appworld" in lowered or "app world" in lowered or "supervisor" in lowered:
            return True
    return False


def _detect_completion_signal(ctx: Context) -> str | None:
    """Return the terminal completion name to display/track for this workspace."""
    completion_name = _detect_completion_tool(ctx)
    if completion_name is not None:
        return completion_name
    if _is_appworld_environment(ctx):
        return "supervisor.complete_task"
    return None


def _is_completion_tool(name: str, ctx: Context) -> bool:
    completion_name = _detect_completion_tool(ctx)
    return bool(completion_name and name == completion_name)


def _code_like_text(args: dict | None) -> str:
    """Best-effort extraction of submitted code from a tool's arguments."""
    if not isinstance(args, dict):
        return ""
    code = args.get("code")
    if isinstance(code, str):
        return code
    parts: list[str] = []
    for key, value in args.items():
        if isinstance(value, str):
            parts.append(f"{key}: {value}")
    return "\n".join(parts)


def _tool_call_contains_completion(name: str, args: dict, ctx: Context) -> bool:
    if _is_completion_tool(name, ctx):
        return True
    if not _is_appworld_environment(ctx):
        return False
    code = _code_like_text(args)
    return bool(code and _COMPLETION_CALL_RE.search(code))


def _observe_tool_result(
    ctx: Context,
    *,
    requested_name: str,
    requested_args: dict,
    executed_name: str,
    executed_args: dict,
    result: str,
    skipped: bool,
) -> None:
    """Update persistent context state after a tool result.

    This is deliberately small and evidence-based. It never blocks a tool call;
    it only makes completion/prerequisite state visible on subsequent planning
    steps.
    """
    if skipped:
        return

    redirected = (
        requested_name != executed_name or requested_args != executed_args
    )

    if _is_appworld_environment(ctx):
        code = _code_like_text(executed_args)
        if not redirected and not code:
            code = _code_like_text(requested_args)
        if code:
            if _SUPERVISOR_CREDENTIAL_RE.search(code):
                ctx._prereq_supervisor_credentials = not _result_indicates_failure(
                    result
                )
            for match in _APP_LOGIN_RE.finditer(code):
                app = match.group(1).lower()
                if app in {"supervisor", "system", "sys", "os"}:
                    continue
                if _result_indicates_failure(result):
                    ctx._prereq_app_logins[app] = "login failed"
                else:
                    # A login call with no explicit failure is treated as
                    # completed, matching the AppWorld shell convention that
                    # API errors are surfaced in the execution output.
                    ctx._prereq_app_logins[app] = "logged in"

    completion_observed = _tool_call_contains_completion(
        executed_name, executed_args, ctx
    )
    if not redirected:
        completion_observed = completion_observed or _tool_call_contains_completion(
            requested_name, requested_args, ctx
        )
    if (
        _is_appworld_environment(ctx)
        and not completion_observed
        and _result_indicates_task_completed(result)
    ):
        completion_observed = True

    if completion_observed and not ctx._completion_tool_called:
        ctx._completion_tool_called = True
        ctx.trace.event(
            "completion_tool_called",
            tool=executed_name,
            turn=ctx._current_turn,
            remaining=ctx.remaining_turns,
        )


def _prerequisite_checklist_text(ctx: Context) -> str:
    """Compact prerequisite status for AppWorld-style authentication setup."""
    if not _is_appworld_environment(ctx):
        return ""
    credential_state = (
        "retrieved" if ctx._prereq_supervisor_credentials else "NOT retrieved"
    )
    parts = [f"supervisor credentials: {credential_state}"]
    if ctx._prereq_app_logins:
        login_bits = [
            f"{app}: {state}"
            for app, state in sorted(ctx._prereq_app_logins.items())
        ]
        parts.append("app logins: " + "; ".join(login_bits))
        if all(state == "logged in" for state in ctx._prereq_app_logins.values()):
            parts.append("(observed prerequisites satisfied)")
        else:
            parts.append("(prerequisites INCOMPLETE)")
    else:
        parts.append("app logins: none observed")
        if ctx._prereq_supervisor_credentials:
            parts.append("(ensure every app required by the task is logged in)")
        else:
            parts.append("(prerequisites INCOMPLETE)")
    return "Prerequisites: " + " | ".join(parts) + "."


def _context_status_message(ctx: Context) -> dict:
    """Compact persistent status shown to the model before each planning step."""
    used = ctx._current_turn
    total = ctx.max_turns
    remaining = ctx.remaining_turns
    completion_name = _detect_completion_signal(ctx)

    parts = [
        f"[Runtime context] Interactions used: {used}/{total} ({remaining} remaining)."
    ]

    if completion_name is not None:
        called = "yes" if ctx._completion_tool_called else "no"
        parts.append(f"{completion_name} called: {called}.")
        if ctx._completion_tool_called:
            parts.append(
                "Task completion has already been recorded; do not call it again. "
                "Provide the final answer without further tool calls."
            )
        elif remaining <= 0:
            parts.append("No tool-using interactions remain; provide the final answer now.")
        elif remaining == 1:
            parts.append(
                f"This is the final tool-using interaction. If the task state is "
                f"satisfied and all prerequisites are met, call {completion_name} "
                "NOW and no other tools. Do not explore or verify further."
            )
        elif remaining <= 3:
            parts.append(
                f"Only {remaining} tool-using interactions remain. Complete "
                f"unfinished prerequisites immediately and call {completion_name} "
                "as soon as the task state is satisfied; do not spend interactions "
                "on extra verification."
            )
        else:
            parts.append(
                f"Once the task state is satisfied, stop additional exploration or "
                f"verification and emit only the terminal completion call "
                f"({completion_name}). The final LLM turn disables tool calls, so "
                "reserve the final tool-using interaction(s) for that terminal call."
            )
    elif remaining <= 0:
        parts.append("No tool-using interactions remain; provide the final answer now.")
    elif remaining == 1:
        parts.append(
            "This is the final tool-using interaction; emit the terminal action or "
            "final answer now."
        )

    prerequisite_text = _prerequisite_checklist_text(ctx)
    if (
        prerequisite_text
        and completion_name is not None
        and not ctx._completion_tool_called
    ):
        parts.append(prerequisite_text)
        if remaining > 0 and "INCOMPLETE" in prerequisite_text:
            parts.append(
                f"Do not call {completion_name} until every required prerequisite "
                "is complete."
            )
        elif remaining > 0 and "ensure every app required" in prerequisite_text:
            parts.append(
                f"Before calling {completion_name}, ensure every app required by "
                "the task is logged in."
            )

    return {"role": "user", "content": " ".join(parts)}


