# Built-in tool dispatch
# ---------------------------------------------------------------------------


def _serialize_assistant(msg) -> dict:
    """Convert an LLM response Message into a plain dict for the next request.

    Preserves `reasoning_content` for models that require it on tool round-trips. Strips
    fields the API rejects on input (`refusal`, `audio`, etc.)."""
    if hasattr(msg, "model_dump"):
        d = msg.model_dump(exclude_none=True)
    elif hasattr(msg, "dict"):
        d = msg.dict(exclude_none=True)
    else:
        d = {"role": getattr(msg, "role", "assistant")}
        if getattr(msg, "content", None) is not None:
            d["content"] = msg.content
        if getattr(msg, "reasoning_content", None) is not None:
            d["reasoning_content"] = msg.reasoning_content
        tcs = getattr(msg, "tool_calls", None)
        if tcs:
            d["tool_calls"] = [
                {
                    "id": tc.id,
                    "type": getattr(tc, "type", "function"),
                    "function": {
                        "name": tc.function.name,
                        "arguments": tc.function.arguments,
                    },
                }
                for tc in tcs
            ]
    if "tool_calls" in d and "content" not in d:
        d["content"] = ""
    for k in (
        "function_call",
        "audio",
        "annotations",
        "refusal",
        "provider_specific_fields",
    ):
        d.pop(k, None)
    return d


def _obj_get(obj: Any, key: str, default: Any = None) -> Any:
    if isinstance(obj, dict):
        return obj.get(key, default)
    return getattr(obj, key, default)


def _make_chat_tool_call(call_id: str, name: str, arguments: str):
    """Create a chat-completions-shaped tool call object."""
    return SimpleNamespace(
        id=call_id,
        type="function",
        function=SimpleNamespace(name=name, arguments=arguments),
    )


def _responses_call_to_chat_tool_call(fc: Any):
    call_id = (
        _obj_get(fc, "call_id")
        or _obj_get(fc, "id")
        or _obj_get(fc, "tool_call_id")
        or ""
    )
    name = _obj_get(fc, "name") or _obj_get(_obj_get(fc, "function", {}), "name") or ""
    arguments = (
        _obj_get(fc, "arguments")
        or _obj_get(_obj_get(fc, "function", {}), "arguments")
        or "{}"
    )
    if not isinstance(arguments, str):
        arguments = json.dumps(arguments, ensure_ascii=False)
    return _make_chat_tool_call(call_id, name, arguments)


def _chat_tool_call_to_common(tc: Any, *, injected: bool = False) -> dict:
    fn = _obj_get(tc, "function", {}) or {}
    args = _obj_get(fn, "arguments", "{}") or "{}"
    if not isinstance(args, str):
        args = json.dumps(args, ensure_ascii=False)
    out = {
        "id": _obj_get(tc, "id", "") or "",
        "name": _obj_get(fn, "name", "") or "",
        "arguments": args,
    }
    if injected:
        out["injected"] = True
    return out


# ---------------------------------------------------------------------------
# Budget / finalization / stall helpers
# ---------------------------------------------------------------------------

_LENGTH_RETRY_EXTRA_TOKENS = 4096
_LENGTH_RETRY_CONTEXT_TAIL = 8
_FINALIZATION_MAX_TURNS = 2
_COMPLETION_ANSWER_KEYS = (
    "answer",
    "final_answer",
    "completed_answer",
    "task_answer",
    "content",
    "result",
    "response",
    "text",
    "value",
    "output",
    "final",
)
_STALL_SAME_SIGNATURE_LIMIT = 3
_STALL_INTROSPECTION_STREAK_LIMIT = 3
_INTROSPECTION_NAME_RE = re.compile(
    r"(^|_)(help|limit|limits|check_limit|check_limits|print|list|show|describe|docs|introspect|inspect|status|debug|env|whoami|pwd|ls|cat)(_|$)",
    re.IGNORECASE,
)
_INTROSPECTION_CODE_RE = re.compile(
    r"__(dict|class|module|name)__|\b(help|dir|type|pprint|repr|globals|locals|vars)\s*\(",
    re.IGNORECASE,
)
_LIMIT_CHECK_CODE_RE = re.compile(
    r"\bapis\.(check_limit|check_limits|get_limit|get_limits|has_limit|rate_limit|limits?)\s*\(",
    re.IGNORECASE,
)


def _completion_tool_name(bundle) -> str:
    names = list(bundle.tool_names or [])
    for exact in ("complete_task", "final_answer"):
        if exact in names:
            return exact
    for name in names:
        if "complete" in name:
            return name
    for name in names:
        if "supervisor" in name:
            return name
    for exact in ("finish", "submit"):
        if exact in names:
            return exact
    for name in names:
        if "submit" in name or "finish" in name:
            return name
    return ""


def _completion_only_schemas(bundle, completion_tool: str) -> list[dict]:
    if not completion_tool:
        return []
    return [
        schema
        for schema in bundle.tool_schemas
        if ((schema.get("function") or {}).get("name")) == completion_tool
    ]


def _extract_completion_answer(args: dict) -> str:
    if not isinstance(args, dict):
        return ""
    for key in _COMPLETION_ANSWER_KEYS:
        value = args.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
        if isinstance(value, dict):
            nested = _extract_completion_answer(value)
            if nested:
                return nested
    return ""


def _is_budget_exhausted_failure(failure: str | None) -> bool:
    if not failure:
        return False
    return (
        "length" in failure
        or "max_output_tokens" in failure
        or "output budget exhausted" in failure
    )


def _max_output_tokens(*, retry: bool = False) -> int:
    base = int(getattr(llm, "MAX_TOKENS", 4096) or 4096)
    if getattr(llm, "REASONING_EFFORT", "") and base < 8192:
        # Reasoning tokens count against the same output budget. Ensure the
        # budget is large enough that reasoning plus a final tool/answer can fit.
        base = 8192
    if retry:
        base += _LENGTH_RETRY_EXTRA_TOKENS
    return base


def _recent_tool_summary(ctx: Context, limit: int = _LENGTH_RETRY_CONTEXT_TAIL) -> str:
    if not ctx.tool_history:
        return ""
    recent = ctx.tool_history[-limit:]
    lines = []
    for rec in recent:
        args = json.dumps(rec.requested_args, ensure_ascii=False, default=str)
        lines.append(
            f"- {rec.executed_name}({args}) -> {rec.result_preview or '(no output)'}"
        )
    return "Recent tool activity:\n" + "\n".join(lines)


def _length_retry_nudge(ctx: Context) -> str:
    completion_tool = getattr(ctx, "_completion_tool", "") or ""
    lines = [
        "Your previous model output exhausted its token budget before producing "
        "a usable next action or final answer.",
        "Do not repeat prior reasoning or re-read long documents. Using the "
        "original question and the recent activity below, decide the single "
        "next step.",
    ]
    if completion_tool:
        lines.append(
            f"If you have enough evidence, call {completion_tool} now with the "
            "final verified answer. If you still need one critical piece of "
            "evidence, emit exactly one concise tool call for it."
        )
    else:
        lines.append(
            "If you still need one critical piece of evidence, emit exactly one "
            "concise tool call for it. Otherwise, provide your best final answer "
            "now as plain text."
        )
    if "appworld_execute" in ctx.workspace.tool_names:
        lines.append(
            "If you are unsure which API to call, use appworld_execute once with "
            "apis.api_docs to look it up."
        )
    return " ".join(lines)


def _reduced_chat_messages(ctx: Context, nudge: str) -> list[dict]:
    system = {"role": "system", "content": ctx.workspace.system_prompt}
    parts = [ctx.question]
    summary = _recent_tool_summary(ctx)
    if summary:
        parts.append(summary)
    parts.append(nudge)
    return [system, {"role": "user", "content": "\n\n".join(parts)}]


def _reduced_responses_input(ctx: Context, nudge: str) -> list[dict]:
    parts = [ctx.question]
    summary = _recent_tool_summary(ctx)
    if summary:
        parts.append(summary)
    parts.append(nudge)
    return [{"role": "user", "content": "\n\n".join(parts)}]


def _is_introspection_tool(name: str, args: dict, ctx: Context | None = None) -> bool:
    if (
        ctx is not None
        and "appworld_execute" in ctx.workspace.tool_names
        and _INTROSPECTION_NAME_RE.search(name)
    ):
        return True
    if name == "appworld_execute":
        code = str(args.get("code") or "")
        if not code.strip():
            return False
        if re.search(r"\bapis\.", code):
            return bool(_LIMIT_CHECK_CODE_RE.search(code))
        if _INTROSPECTION_CODE_RE.search(code):
            return True
    return False


def _nudge_for_stall(ctx: Context, name: str, args: dict) -> str:
    completion_tool = getattr(ctx, "_completion_tool", "") or ""
    has_appworld = "appworld_execute" in ctx.workspace.tool_names
    if completion_tool:
        if has_appworld:
            return (
                f"You are making repeated non-progress tool calls ({name}). "
                "Stop introspecting or re-checking limits. If you are unsure how "
                "to perform the required action, look up the correct API with "
                "apis.api_docs, then execute it and verify the result. As soon as "
                f"you have a verified answer, call {completion_tool} with that "
                "answer. Do not call any other introspection or limit-checking "
                "tools."
            )
        return (
            f"You are making repeated non-progress tool calls ({name}). Stop "
            "introspecting or re-checking limits. If you need API details, consult "
            "the API documentation; otherwise use the evidence you already have. "
            f"When you have a verified answer, call {completion_tool} with it."
        )
    if has_appworld:
        return (
            f"You are making repeated non-progress tool calls ({name}). Stop "
            "introspecting or re-checking limits. If you are unsure how to "
            "perform the required action, use appworld_execute once with "
            "apis.api_docs to look up the correct API, then execute it and "
            "verify the result. Then provide the final answer."
        )
    return (
        f"You are making repeated non-progress tool calls ({name}). Stop "
        "introspecting or re-checking limits. Use the evidence you already have "
        "and provide the final answer now. If you need API details, consult the "
        "API documentation first."
    )


def _append_user_nudge(messages, resp_input, use_responses_api: bool, nudge: str) -> None:
    if not nudge:
        return
    msg = {"role": "user", "content": nudge}
    if use_responses_api:
        resp_input.append(msg)
    else:
        messages.append(msg)


def _budget_warning(ctx: Context) -> str:
    """Return a short, low-budget instruction for the model, or "".

    The final tool execution is reserved for the workspace completion tool when
    one exists. Surface that reservation before the LLM call so the model has a
    chance to finish cleanly instead of hitting the hard execution cap.
    """
    remaining = ctx.remaining_tool_calls
    completion_tool = getattr(ctx, "_completion_tool", "") or ""
    if completion_tool:
        if remaining <= 0:
            return (
                "No exploratory tool executions remain. The only available "
                f"action is the reserved {completion_tool} call. Call "
                f"{completion_tool} now with the final verified answer and do "
                "not call any other tool."
            )
        if remaining == 1:
            return (
                f"Only one tool execution remains and it is reserved for "
                f"{completion_tool}. Call {completion_tool} now with the final "
                "verified answer. Do not call any other tool."
            )
        if remaining == 2:
            return (
                f"Only two tool executions remain, and the final one is "
                f"reserved for {completion_tool}. If you still need one critical "
                "piece of evidence, use at most one exploratory tool call now; "
                f"otherwise call {completion_tool} with the final verified answer."
            )
    else:
        if remaining <= 0:
            return (
                "No tool executions remain. Provide your best final answer now "
                "as plain text. Do not call any more tools."
            )
        if remaining == 1:
            return (
                "Only one tool execution remains. Use it only if it is essential "
                "for the final answer; otherwise provide your final answer now "
                "as plain text."
            )
    return ""


class _ResponsesMiddlewareAdapter:
    """Chat-like response facade for middleware on Responses API runs."""

    def __init__(
        self,
        raw: Any,
        content: str,
        reasoning: str,
        function_calls: list,
        *,
        original_call_ids: set[str] | None = None,
    ):
        self.raw_response = raw
        self._content = content or ""
        self._reasoning_content = reasoning or ""
        self._reasoning = reasoning or ""
        self._tool_calls = [
            _responses_call_to_chat_tool_call(fc) for fc in function_calls
        ]
        if original_call_ids is None:
            original_call_ids = {
                _obj_get(tc, "id", "") or "" for tc in self._tool_calls
            }
        self._original_call_ids = set(original_call_ids)
        self.choices = [
            SimpleNamespace(
                message=SimpleNamespace(
                    role="assistant",
                    content=self._content,
                    reasoning_content=self._reasoning_content,
                    tool_calls=self._tool_calls,
                ),
                finish_reason="tool_calls" if self._tool_calls else "stop",
            )
        ]

    @property
    def content(self) -> str:
        return self._content

    @content.setter
    def content(self, value: str | None) -> None:
        self._content = value or ""
        try:
            self.choices[0].message.content = self._content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning_content(self) -> str:
        return self._reasoning_content

    @reasoning_content.setter
    def reasoning_content(self, value: str | None) -> None:
        self._reasoning_content = value or ""
        try:
            self.choices[0].message.reasoning_content = self._reasoning_content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning(self) -> str:
        return self._reasoning

    @reasoning.setter
    def reasoning(self, value: str | None) -> None:
        self._reasoning = value or ""

    @property
    def tool_calls(self) -> list:
        return self._tool_calls

    @tool_calls.setter
    def tool_calls(self, value: list | None) -> None:
        self._tool_calls = list(value or [])
        try:
            self.choices[0].message.tool_calls = self._tool_calls
            self.choices[0].finish_reason = "tool_calls" if self._tool_calls else "stop"
        except (AttributeError, IndexError, TypeError):
            pass

    def sync_from_message(self) -> None:
        msg = self.choices[0].message
        msg_content = getattr(msg, "content", None)
        if msg_content is not None:
            self._content = msg_content
        elif getattr(self, "content", None) is not None:
            msg.content = self._content
        msg_reasoning = getattr(msg, "reasoning_content", None)
        if msg_reasoning is not None:
            self._reasoning_content = msg_reasoning
            self._reasoning = self._reasoning or msg_reasoning
        msg_tool_calls = getattr(msg, "tool_calls", None)
        self._tool_calls = list(msg_tool_calls or [])
        msg.tool_calls = self._tool_calls

    def common_tool_calls(self) -> list[dict]:
        self.sync_from_message()
        out: list[dict] = []
        for tc in self.tool_calls:
            call_id = _obj_get(tc, "id", "") or ""
            out.append(
                _chat_tool_call_to_common(
                    tc,
                    injected=call_id not in self._original_call_ids,
                )
            )
        return out


def _ensure_responses_adapter(
    response: Any,
    *,
    original_call_ids: set[str],
) -> _ResponsesMiddlewareAdapter:
    """Normalize middleware return values back into the Responses facade."""
    if isinstance(response, _ResponsesMiddlewareAdapter):
        return response

    choices = getattr(response, "choices", None)
    if choices:
        msg = choices[0].message
        adapter = _ResponsesMiddlewareAdapter(
            response,
            getattr(msg, "content", None) or getattr(response, "content", "") or "",
            getattr(msg, "reasoning_content", None)
            or getattr(response, "reasoning_content", None)
            or getattr(response, "reasoning", None)
            or "",
            [],
            original_call_ids=original_call_ids,
        )
        adapter.choices = choices
        adapter.sync_from_message()
        return adapter

    if getattr(response, "output", None) is not None:
        content, reasoning, function_calls = llm.extract_responses_output(response)
        return _ResponsesMiddlewareAdapter(
            response,
            content,
            reasoning,
            function_calls,
            original_call_ids=original_call_ids,
        )

    adapter = _ResponsesMiddlewareAdapter(
        response,
        getattr(response, "content", None) or "",
        getattr(response, "reasoning_content", None)
        or getattr(response, "reasoning", None)
        or "",
        [],
        original_call_ids=original_call_ids,
    )
    adapter.tool_calls = list(getattr(response, "tool_calls", None) or [])
    return adapter


def _middleware_message_key(msg: Any) -> str:
    try:
        return json.dumps(msg, ensure_ascii=False, sort_keys=True, default=str)
    except Exception:
        return repr(msg)


def _middleware_additions(before: list, after: list) -> list:
    """Return messages added by before_llm hooks, even if hooks copied lists."""
    remaining: dict[str, int] = {}
    for msg in before:
        key = _middleware_message_key(msg)
        remaining[key] = remaining.get(key, 0) + 1

    added = []
    for msg in after:
        key = _middleware_message_key(msg)
        if remaining.get(key, 0) > 0:
            remaining[key] -= 1
        else:
            added.append(msg)
    return added


def _responses_input_from_middleware_message(msg: Any) -> dict | None:
    role = _obj_get(msg, "role", "") or ""
    content = _obj_get(msg, "content", "") or ""
    if not content or role not in {"system", "developer", "user", "assistant"}:
        return None
    # Responses API already receives the main system prompt via instructions;
    # runtime middleware nudges are safest as developer messages.
    if role == "system":
        role = "developer"
    return {"role": role, "content": content}


def _middleware_assistant_message(content: str, tc_list: list[dict]) -> dict:
    msg = {"role": "assistant", "content": content or ""}
    if tc_list:
        msg["tool_calls"] = [
            {
                "id": tc["id"],
                "type": "function",
                "function": {
                    "name": tc["name"],
                    "arguments": tc["arguments"],
                },
            }
            for tc in tc_list
        ]
    return msg


async def _dispatch_builtin(name: str, args: dict, ctx: Context) -> str | None:
    """Returns a string result for built-ins; None if `name` is not built-in."""
    if name == "web_search":
        ctx.search_calls += 1
        query = (args.get("query") or "").strip()
        if not query:
            return "web_search requires a non-empty `query`."
        result_text, items = await web_search_structured(query)
        ctx.trace.save_search(ctx.search_calls, query, result_text)
        urls = [item["url"] for item in items]
        ctx.searches.append(
            SearchRecord(
                idx=ctx.search_calls,
                query=query,
                turn=ctx._current_turn,
                items=items,
                urls=urls,
            )
        )
        return result_text

    if name == "read_url":
        ctx.read_calls += 1
        url = (args.get("url") or "").strip()
        focus = (args.get("focus") or "").strip()
        if not url:
            return "read_url requires a non-empty `url`."
        page = await reader.read_url_with_raw(
            url,
            focus or "general relevance",
            extract_prompt=ctx.workspace.extract_prompt,
        )
        extracted = page["extracted"]
        artifact_path = ctx.trace.save_page(
            url, focus, extracted, raw_text=page.get("raw", "")
        )
        success = True
        failure_type = None
        if "[reader] fetch failed" in extracted:
            success, failure_type = False, "fetch_failed"
        elif "[reader] extract error" in extracted:
            success, failure_type = False, "extract_error"
        elif "[reader] no relevant content" in extracted:
            success, failure_type = False, "no_content"
        ctx.reads.append(
            ReadRecord(
                idx=ctx.read_calls,
                url=url,
                focus=focus,
                turn=ctx._current_turn,
                success=success,
                failure_type=failure_type,
                artifact_path=artifact_path,
                content_preview=extracted[:500],
            )
        )
        return extracted

    return None


def _normalize_tool_result(value: Any, ctx: Context, *, tool: str) -> tuple[str, dict]:
    """Normalize custom workspace tool returns into content + metadata."""
    if isinstance(value, ToolResult):
        metadata = value.metadata if isinstance(value.metadata, dict) else {}
        if value.metadata is not metadata:
            ctx.trace.event(
                "tool_result_warning", tool=tool, reason="metadata_not_dict"
            )
        return str(value.content), copy.deepcopy(metadata)
    if isinstance(value, str):
        return value, {}
    if value is None:
        ctx.trace.event("tool_result_warning", tool=tool, reason="none_return")
        return "", {}
    ctx.trace.event(
        "tool_result_warning",
        tool=tool,
        reason=f"unexpected_return_type: {type(value).__name__}",
    )
    return str(value), {}


async def _run_before_final_hooks(
    candidate: str, ctx: Context
) -> tuple[str, str, str | None]:
    """Run final-answer gates. Returns (action, answer, feedback)."""
    answer = candidate
    for mw in ctx.workspace.middlewares:
        hook = getattr(mw, "before_final", None)
        if not hook:
            continue
        try:
            ret = await hook(answer, ctx)
        except Exception as e:
            ctx.trace.event(
                "middleware_error", hook="before_final", mw=mw.name, error=str(e)
            )
            continue

        if ret is None:
            ctx.trace.event("before_final_accept", mw=mw.name, mode="implicit")
            continue
        if not isinstance(ret, dict):
            ctx.trace.event(
                "middleware_warning",
                hook="before_final",
                mw=mw.name,
                reason=f"unexpected_return_type: {type(ret).__name__}",
            )
            continue

        action = ret.get("action", "accept")
        if action == "accept":
            ctx.trace.event("before_final_accept", mw=mw.name, mode="explicit")
            continue

        if action == "replace":
            if "answer" not in ret:
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="replace_missing_answer",
                )
                continue
            answer = str(ret.get("answer") or "")
            ctx.trace.event("before_final_replace", mw=mw.name, length=len(answer))
            continue

        if action == "continue":
            feedback = ret.get("feedback")
            if not isinstance(feedback, str) or not feedback.strip():
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="continue_missing_feedback",
                )
                continue
            if ctx.remaining_turns <= 0:
                ctx.trace.event(
                    "before_final_continue_rejected", mw=mw.name, reason="last_turn"
                )
                return "accept", answer, None
            if ctx._final_continues >= ctx._final_continue_max:
                ctx.trace.event(
                    "before_final_continue_rejected",
                    mw=mw.name,
                    reason="budget_exceeded",
                    budget=ctx._final_continue_max,
                )
                return "accept", answer, None
            ctx._final_continues += 1
            ctx.trace.event(
                "before_final_continue",
                mw=mw.name,
                count=ctx._final_continues,
                feedback=feedback,
            )
            return "continue", answer, feedback

        ctx.trace.event(
            "middleware_warning",
            hook="before_final",
            mw=mw.name,
            reason=f"unknown_action: {action}",
        )

    return "accept", answer, None


async def _dispatch(name: str, args: dict, ctx: Context) -> str:
    if name not in ctx.workspace.tool_names:
        return f"Unavailable tool: {name}"
    signature = name + ":" + json.dumps(args, sort_keys=True, ensure_ascii=False, default=str)
    ctx._stall_signature_counts[signature] += 1
    ctx._last_tool_signature = signature
    if _is_introspection_tool(name, args, ctx):
        ctx._introspection_streak += 1
    else:
        ctx._introspection_streak = 0

    original_name = name
    original_args = copy.deepcopy(args)
    action = "executed"
    skipped = False
    result = ""
    result_metadata: dict = {}

    # before_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.before_tool:
            try:
                ret = await mw.before_tool(name, args, ctx)
                if isinstance(ret, dict):
                    act = ret.get("action")
                    if act == "skip":
                        if action == "redirected":
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="skip_after_redirect",
                            )
                        else:
                            result = str(ret.get("result", ""))
                            action = "skipped"
                            skipped = True
                            ctx._tool_skips += 1
                            ctx.trace.event(
                                "before_tool_skip", mw=mw.name, tool=original_name
                            )
                            break
                    elif act == "redirect":
                        new_name = ret.get("name")
                        new_args = ret.get("args")
                        if (
                            isinstance(new_name, str)
                            and new_name
                            and isinstance(new_args, dict)
                        ):
                            ctx.trace.event(
                                "before_tool_redirect",
                                mw=mw.name,
                                from_tool=original_name,
                                to_tool=new_name,
                            )
                            name, args = new_name, new_args
                            action = "redirected"
                            ctx._tool_redirects += 1
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="invalid_redirect_payload",
                            )
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason=f"unknown_action: {act}",
                        )
                elif isinstance(ret, tuple):
                    if (
                        len(ret) == 2
                        and isinstance(ret[0], str)
                        and isinstance(ret[1], dict)
                    ):
                        name, args = ret
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason="invalid_tuple_return",
                        )
                elif ret is not None:
                    ctx.trace.event(
                        "middleware_warning",
                        hook="before_tool",
                        mw=mw.name,
                        reason=f"unexpected_return_type: {type(ret).__name__}",
                    )
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="before_tool", mw=mw.name, error=str(e)
                )

    # execution (skipped if before_tool set skip)
    if not skipped:
        if name not in ctx.workspace.tool_names:
            return f"Unavailable tool: {name}"
        builtin = await _dispatch_builtin(name, args, ctx)
        if builtin is not None:
            result = builtin
        elif name in ctx.workspace.extra_tools:
            try:
                raw_result = await ctx.workspace.extra_tools[name](args, ctx)
                result, result_metadata = _normalize_tool_result(
                    raw_result, ctx, tool=name
                )
            except Exception as e:
                result = f"workspace tool {name!r} error: {e}"
        else:
            result = f"Unknown tool: {name}"

    if not skipped and ctx._completion_tool and name == ctx._completion_tool:
        # Only a successful completion call may terminate the run. Tool-wrapper
        # errors are returned as strings such as "workspace tool '...' error";
        # do not treat those as a successful supervisor-completion call.
        if (
            not result.startswith("workspace tool ")
            and not result.startswith("Unknown tool:")
            and not result.startswith("Unavailable tool:")
        ):
            completion_answer = _extract_completion_answer(args)
            if completion_answer:
                ctx._completion_tool_called = True
                ctx.state["completion_answer"] = completion_answer
        else:
            ctx.trace.event(
                "completion_tool_error",
                tool=name,
                result_preview=result[:200],
            )

    # after_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.after_tool:
            try:
                ret = await mw.after_tool(name, args, result, ctx)
                if isinstance(ret, dict):
                    result = str(ret.get("result", result))
                    if "metadata" in ret:
                        if isinstance(ret["metadata"], dict):
                            result_metadata.update(copy.deepcopy(ret["metadata"]))
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="after_tool",
                                mw=mw.name,
                                reason="metadata_not_dict",
                            )
                    inject_list = ret.get("inject", [])
                    if inject_list:
                        inj = inject_list[0]
                        if (
                            not isinstance(inj, dict)
                            or not isinstance(inj.get("name"), str)
                            or not inj["name"]
                            or not isinstance(inj.get("args", {}), dict)
                        ):
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="malformed_payload",
                            )
                        elif ctx._in_injected_call:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="recursion_guard",
                            )
                        elif ctx._pending_injections:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="one_per_turn",
                            )
                        else:
                            inj.setdefault("args", {})
                            ctx._pending_injections.append(inj)
                            ctx.trace.event(
                                "after_tool_inject_queued", mw=mw.name, tool=inj["name"]
                            )
                elif isinstance(ret, str):
                    result = ret
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="after_tool", mw=mw.name, error=str(e)
                )

    _observe_tool_result(
        ctx,
        requested_name=original_name,
        requested_args=original_args,
        executed_name=name,
        executed_args=args,
        result=result,
        skipped=skipped,
    )

    # record ToolCallRecord (single exit point)
    ctx._tool_seq += 1
    rec = ToolCallRecord(
        seq=ctx._tool_seq,
        requested_name=original_name,
        requested_args=original_args,
        executed_name=name,
        executed_args=copy.deepcopy(args),
        turn=ctx._current_turn,
        result_preview=result[:500],
        result_metadata=copy.deepcopy(result_metadata),
        action=action,
        source="middleware_inject" if ctx._in_injected_call else "model",
    )
    ctx.tool_history.append(rec)
    ctx.current_turn_calls.append(rec)

    if (
        ctx._stall_nudges < 3
        and not ctx._stall_nudge_pending
        and (
            ctx._introspection_streak >= _STALL_INTROSPECTION_STREAK_LIMIT
            or ctx._stall_signature_counts.get(signature, 0)
            >= _STALL_SAME_SIGNATURE_LIMIT
        )
    ):
        ctx._stall_nudge_pending = _nudge_for_stall(ctx, name, args) or ""

    return result


# ---------------------------------------------------------------------------
# Main loop
# ---------------------------------------------------------------------------


async def run(
    question: str,
    *,
    runs_root: Path | str = "runs",
    max_turns: int = 100,
    model: str | None = None,
    workspace_dir: str | Path | None = None,
    editor: bool = False,
    working_dir: str | Path | None = None,
    llm_config: dict | None = None,
    web_config: dict | None = None,
    debug_llm_io: bool = False,
) -> dict[str, Any]:
    llm.configure(llm_config or {})
    web_settings.configure(web_config or {})
    runs_root = Path(runs_root)
    runs_root.mkdir(parents=True, exist_ok=True)
    if editor:
        from .editor import bundle as editor_bundle

        bundle = editor_bundle(Path(workspace_dir))
    else:
        bundle = ws_mod.load(workspace_dir or ws_mod.SEED_WORKSPACE)
        from .web_config import validate_config

        validate_config(bundle.tool_names)
    if working_dir is not None:
        from .editor import attach

        attach(bundle, Path(working_dir))

    model = model or llm.DEFAULT_MODEL
    trace = TraceWriter(
        runs_root, question, config={"llm": llm_config, "web": web_config}
    )
    trace.event(
        "workspace",
        root=str(bundle.root),
        tools=bundle.tool_names,
        middlewares=[m.name for m in bundle.middlewares],
        sub_agents=list(bundle.sub_agents.keys()),
    )
    ctx = Context(
        workspace=bundle,
        trace=trace,
        working_dir=Path(working_dir).resolve() if working_dir else Path.cwd(),
        sub_agents=bundle.sub_agents,
        question=question,
        run_id=trace.dir.name,
        run_dir=str(trace.dir),
        model=model,
        max_turns=max_turns,
    )
    completion_tool = _completion_tool_name(bundle)
    ctx._completion_tool = completion_tool
    ctx.max_tool_calls = max(1, max_turns)
    trace.event(
        "tool_budget",
        max_tool_calls=ctx.max_tool_calls,
        completion_tool=completion_tool,
    )
    stop_reason = "max_turns"
    answer = ""

    _log_dir = trace.dir / "log" if debug_llm_io else None
    if _log_dir is not None:
        _log_dir.mkdir(exist_ok=True)

    use_responses_api = llm.is_openai_model(model)
    responses_session_id = uuid.uuid4().hex if use_responses_api else None
    llm_config = {
        "model": model,
        "api": "responses" if use_responses_api else "chat_completions",
        "reasoning_effort": llm.REASONING_EFFORT,
        "max_output_tokens": _max_output_tokens(),
        "session_id": responses_session_id,
    }
    trace.event("llm_config", **llm_config)
    response_history: list = []
    responses_tools: list[dict] | None = None
    reasoning_cfg: dict | None = None
    resp_input: list = []
    if use_responses_api:
        responses_tools = llm.chat_tools_to_responses(bundle.tool_schemas)
        reasoning_cfg = (
            {"effort": llm.REASONING_EFFORT} if llm.REASONING_EFFORT else None
        )
        resp_input = [{"role": "user", "content": question}]
        trace.event("responses_api", model=model)

    completion_only_chat: list[dict] | None = None
    completion_only_responses: list[dict] | None = None
    if completion_tool:
        completion_only_chat = _completion_only_schemas(bundle, completion_tool)
        if use_responses_api:
            completion_only_responses = llm.chat_tools_to_responses(
                completion_only_chat
            )

    # Chat Completions sends this message list directly. Responses keeps this
    # view for middleware and replays complete output items for model continuity.
    messages: list[dict] = [
        {"role": "system", "content": bundle.system_prompt},
        {"role": "user", "content": question},
    ]

    last_turn = 0
    finalization_turns = _FINALIZATION_MAX_TURNS if completion_tool else 0
    total_turns = max_turns + finalization_turns
    for turn in range(1, total_turns + 1):
        last_turn = turn
        ctx._current_turn = turn
        ctx.current_turn_calls = []

        response_input = resp_input
        if use_responses_api:
            before_messages = copy.deepcopy(messages)
            for mw in bundle.middlewares:
                if mw.before_llm:
                    try:
                        messages = await mw.before_llm(messages, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="before_llm",
                            mw=mw.name,
                            error=str(e),
                        )
            additions = [
                x
                for m in _middleware_additions(before_messages, messages)
                if (x := _responses_input_from_middleware_message(m)) is not None
            ]
            if additions:
                response_input = resp_input + additions
        else:
            for mw in bundle.middlewares:
                if mw.before_llm:
                    try:
                        messages = await mw.before_llm(messages, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="before_llm",
                            mw=mw.name,
                            error=str(e),
                        )

        is_finalization = turn > max_turns
        if is_finalization and completion_tool:
            finalization_prompt = (
                "You have reached the finalization stage. No more exploratory "
                f"tool calls are allowed. Call {completion_tool} now with your "
                "final verified answer for the original question. If you are "
                "missing evidence, give your best answer and note the "
                "uncertainty. Do NOT call any other tool."
            )
            if use_responses_api:
                response_input = response_input + [
                    {"role": "user", "content": finalization_prompt}
                ]
                messages.append({"role": "user", "content": finalization_prompt})
            else:
                messages.append({"role": "user", "content": finalization_prompt})

        if not is_finalization:
            if turn < max_turns or not completion_tool:
                status_message = _context_status_message(ctx)
                if status_message:
                    if use_responses_api:
                        response_input = response_input + [status_message]
                        messages.append(status_message)
                    else:
                        messages.append(status_message)
            budget_nudge = _budget_warning(ctx)
            if budget_nudge:
                if use_responses_api:
                    response_input = response_input + [
                        {"role": "user", "content": budget_nudge}
                    ]
                    messages.append({"role": "user", "content": budget_nudge})
                else:
                    messages.append({"role": "user", "content": budget_nudge})

        if _log_dir is not None:
            _req_log: dict[str, Any] = {"turn": turn, "model": model}
            if use_responses_api:
                _req_log["type"] = "responses"
                _req_log["input"] = response_history + response_input
                _req_log["continuation"] = "stateless"
                _req_log["session_id"] = responses_session_id
                _req_log["reasoning"] = reasoning_cfg
                _req_log["max_output_tokens"] = _max_output_tokens()
            else:
                _req_log["type"] = "chat"
                _req_log["messages"] = messages
                _req_log["tools_count"] = (
                    len(bundle.tool_schemas) if bundle.tool_schemas else 0
                )
            _req_file = _log_dir / f"turn_{turn:03d}_request.json"
            trace.write_json(_req_file, _req_log)

        budget_exhausted = ctx.remaining_tool_calls <= 0
        if completion_tool and (ctx.remaining_tool_calls <= 1 or is_finalization):
            # The final tool execution is reserved for the completion/submit tool.
            force_final_text = False
            if use_responses_api:
                _tc = "required" if completion_only_responses else "none"
            else:
                _tc = (
                    {"type": "function", "function": {"name": completion_tool}}
                    if completion_only_chat
                    else "none"
                )
            _tools_resp = completion_only_responses or None
            _tools_chat = completion_only_chat or None
        else:
            force_final_text = not completion_tool and (
                turn == max_turns or budget_exhausted
            )
            _tc = "none" if force_final_text else "auto"
            _tools_resp = None if force_final_text else responses_tools
            _tools_chat = None if force_final_text else bundle.tool_schemas

        _llm_last_err: Exception | None = None
        _length_retry_done = False
        while True:
            _llm_last_err = None
            for _attempt in range(1, llm.LLM_MAX_RETRIES + 1):
                try:
                    request_started = time.monotonic()
                    _max_tokens = _max_output_tokens(retry=_length_retry_done)
                    if use_responses_api:
                        resp = await llm.responses(
                            response_history + response_input,
                            model=model,
                            instructions=bundle.system_prompt,
                            tools=_tools_resp,
                            tool_choice=_tc,
                            reasoning=reasoning_cfg,
                            session_id=responses_session_id,
                            max_output_tokens=_max_tokens,
                        )
                    else:
                        resp = await llm.chat(
                            messages,
                            model=model,
                            tools=_tools_chat,
                            tool_choice=_tc,
                            max_tokens=_max_tokens,
                        )

                    if _log_dir is not None:
                        try:
                            _resp_data = (
                                resp.model_dump()
                                if hasattr(resp, "model_dump")
                                else repr(resp)
                            )
                        except Exception:
                            _resp_data = repr(resp)
                        _resp_file = _log_dir / f"turn_{turn:03d}_response.json"
                        trace.write_json(_resp_file, {"turn": turn, "response": _resp_data})
                    _llm_last_err = None
                    break  # success

                except Exception as e:
                    _llm_last_err = e
                    logger.warning(
                        "LLM call failed (turn %d, attempt %d/%d): %s",
                        turn,
                        _attempt,
                        llm.LLM_MAX_RETRIES,
                        trace.redact(str(e)),
                    )
                    if llm.is_fatal_api_error(e):
                        break
                    if _attempt < llm.LLM_MAX_RETRIES:
                        await asyncio.sleep(2**_attempt)  # 2s, 4s

            if _llm_last_err is not None:
                e = _llm_last_err
                http_detail = {}
                for key in ("status_code", "llm_provider", "model"):
                    val = getattr(e, key, None)
                    if val is not None:
                        http_detail[key] = val
                cur = e
                while cur is not None:
                    http_resp = getattr(cur, "response", None)
                    if http_resp is not None and hasattr(http_resp, "status_code"):
                        http_detail["status"] = getattr(http_resp, "status_code", None)
                        http_detail["url"] = str(getattr(http_resp, "url", ""))
                        http_detail["headers"] = dict(getattr(http_resp, "headers", {}))
                        try:
                            http_detail["body"] = http_resp.text
                        except Exception:
                            http_detail["body"] = repr(getattr(http_resp, "content", b""))
                        break
                    cur = getattr(cur, "original_exception", None) or getattr(
                        cur, "__cause__", None
                    )
                logger.warning(
                    "LLM call failed (attempts=%d, turn=%d): %s\nHTTP detail: %s",
                    _attempt,
                    turn,
                    trace.redact(str(e)),
                    trace.redact(json.dumps(http_detail, ensure_ascii=False, default=str)),
                )
                stop_reason = f"llm_error: {e}"
                break

            usage = {
                "role": "primary",
                "turn": turn,
                "model": model,
                "call_id": getattr(resp, "id", None),
                "latency_seconds": time.monotonic() - request_started,
                "usage": llm.usage_dict(resp),
            }
            ctx.model_usage.append(usage)
            trace.event("model_usage", **usage)
            failure = llm.response_error(resp, responses_api=use_responses_api)
            if not failure:
                break

            if _is_budget_exhausted_failure(failure) and not _length_retry_done:
                _length_retry_done = True
                ctx._length_retry_used = True
                trace.event("llm_length_retry", turn=turn, error=failure)
                nudge = _length_retry_nudge(ctx)
                if use_responses_api:
                    response_history = []
                    response_input = _reduced_responses_input(ctx, nudge)
                    resp_input = copy.deepcopy(response_input)
                    messages = _reduced_chat_messages(ctx, nudge)
                else:
                    messages = _reduced_chat_messages(ctx, nudge)
                continue

            # Non-budget failure, or the length retry also exhausted the budget.
            # If the failed response still contains tool calls, execute them in
            # the shared execution path below instead of terminating with an
            # unexecuted assistant tool call as the last message.
            if use_responses_api:
                _, _, partial_fcs = llm.extract_responses_output(resp)
                has_recoverable_tool_calls = bool(partial_fcs)
            elif resp.choices:
                msg = resp.choices[0].message
                has_recoverable_tool_calls = bool(getattr(msg, "tool_calls", None))
            else:
                has_recoverable_tool_calls = False

            if has_recoverable_tool_calls:
                trace.event(
                    "llm_error_recover_tool_calls",
                    turn=turn,
                    error=failure,
                )
                break

            if use_responses_api:
                partial, _, _ = llm.extract_responses_output(resp)
                messages.append({"role": "assistant", "content": partial})
            elif resp.choices:
                messages.append(_serialize_assistant(resp.choices[0].message))
            stop_reason = f"llm_error: {failure}"
            trace.event("llm_error", turn=turn, error=failure)
            break

        if stop_reason.startswith("llm_error"):
            break

        if use_responses_api:
            response_history.extend(copy.deepcopy(response_input))
            response_history.extend(
                item.model_dump(mode="json", exclude_none=True)
                if hasattr(item, "model_dump")
                else copy.deepcopy(item)
                for item in (resp.output or [])
            )
            content, reasoning, function_calls = llm.extract_responses_output(resp)
            adapter = _ResponsesMiddlewareAdapter(
                resp, content, reasoning, function_calls
            )
            original_call_ids = set(adapter._original_call_ids)
            for mw in bundle.middlewares:
                if mw.after_llm:
                    try:
                        updated = await mw.after_llm(adapter, ctx)
                        adapter = _ensure_responses_adapter(
                            updated,
                            original_call_ids=original_call_ids,
                        )
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="after_llm",
                            mw=mw.name,
                            error=str(e),
                        )
            adapter.sync_from_message()
            content = adapter.content or ""
            reasoning = adapter.reasoning_content or adapter.reasoning or ""
            tc_list = adapter.common_tool_calls()
        else:
            for mw in bundle.middlewares:
                if mw.after_llm:
                    try:
                        resp = await mw.after_llm(resp, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="after_llm",
                            mw=mw.name,
                            error=str(e),
                        )

            # Normalize response into common variables
            tc_list = []
            msg = resp.choices[0].message
            content = msg.content or ""
            reasoning = getattr(msg, "reasoning_content", None) or ""
            for tc in getattr(msg, "tool_calls", None) or []:
                tc_list.append(_chat_tool_call_to_common(tc))

        trace.event(
            "assistant",
            turn=turn,
            content=content,
            reasoning=reasoning,
            n_tool_calls=len(tc_list),
        )

        if not tc_list:
            if not content.strip():
                if force_final_text or is_finalization:
                    # Let the post-loop forced completion/text turn try again
                    # rather than discarding the run on an empty final turn.
                    stop_reason = "final_turn_empty"
                    break
                stop_reason = "llm_error: model returned no final answer text"
                break
            candidate_answer = content
            final_action, final_answer, feedback = await _run_before_final_hooks(
                candidate_answer,
                ctx,
            )
            messages.append({"role": "assistant", "content": final_answer})
            if final_action == "continue" and feedback:
                messages.append({"role": "user", "content": feedback})
                if use_responses_api:
                    resp_input = [{"role": "user", "content": feedback}]
                continue
            if _contains_unexecuted_tool_call_markup(final_answer):
                trace.event(
                    "unexecuted_tool_call_markup_detected",
                    turn=turn,
                    length=len(final_answer),
                )
                nudge = (
                    "Your previous response contains tool-call markup, but those "
                    "tool calls were not executed through the available tool "
                    "interface. Either call the tools through the tool interface "
                    "so they are actually executed, or provide your final answer "
                    "as plain text without tool-call markup."
                )
                messages.append({"role": "user", "content": nudge})
                if use_responses_api:
                    resp_input = [{"role": "user", "content": nudge}]
                continue
            if (
                completion_tool
                and not ctx._completion_tool_called
                and not is_finalization
            ):
                nudge = (
                    f"You returned a text answer, but this task requires a "
                    f"{completion_tool} tool call to finish. In the next turn, "
                    f"call {completion_tool} with the final answer as the answer "
                    "argument. Do not only describe it."
                )
                messages.append({"role": "user", "content": nudge})
                if use_responses_api:
                    resp_input = [{"role": "user", "content": nudge}]
                continue
            answer = final_answer
            stop_reason = "no_tool_calls"
            break

        if use_responses_api:
            messages.append(_middleware_assistant_message(content, tc_list))
        else:
            messages.append(_serialize_assistant(msg))

        tool_outputs: list[dict] = []
        injected_tool_messages: list[dict] = []
        for tc in tc_list:
            name = tc["name"]
            try:
                args = json.loads(tc["arguments"])
            except json.JSONDecodeError:
                args = {}
            before_tool_seq = ctx._tool_seq
            tool_error = False
            if (
                completion_tool
                and name != completion_tool
                and (is_finalization or ctx.remaining_tool_calls <= 1)
            ):
                result = (
                    "Tool execution budget exhausted for exploratory calls. The "
                    f"remaining execution is reserved for {completion_tool}. Call "
                    f"{completion_tool} with the final answer now."
                )
                trace.event(
                    "tool_execution_reserved",
                    turn=turn,
                    requested_tool=name,
                    reserved_for=completion_tool,
                )
            elif not completion_tool and ctx.remaining_tool_calls <= 0:
                result = (
                    "Tool execution budget exhausted. Provide your best final "
                    "answer as plain text now; do not call any more tools."
                )
                trace.event(
                    "tool_execution_reserved",
                    turn=turn,
                    requested_tool=name,
                    reserved_for="final_text_answer",
                )
            else:
                try:
                    result = await _dispatch(name, args, ctx)
                except Exception as e:
                    result = f"tool error: {e}"
                    tool_error = True
            observation = format_tool_observation(
                name, args, result, is_error=tool_error
            )
            result_metadata = {}
            if ctx.tool_history and ctx.tool_history[-1].seq > before_tool_seq:
                result_metadata = copy.deepcopy(ctx.tool_history[-1].result_metadata)
            trace.event(
                "tool_call",
                turn=turn,
                tool=name,
                args=args,
                result=result,
                result_metadata=result_metadata,
                search=ctx.search_calls,
                read=ctx.read_calls,
            )
            if use_responses_api:
                if not tc.get("injected"):
                    tool_outputs.append(
                        {
                            "type": "function_call_output",
                            "call_id": tc["id"],
                            "output": observation,
                        }
                    )
                else:
                    injected_tool_messages.append(
                        {
                            "role": "user",
                            "content": (
                                "Runtime middleware executed an additional tool call.\n"
                                + observation
                            ),
                        }
                    )
            else:
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": tc["id"],
                        "content": observation,
                    }
                )
            if use_responses_api:
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": tc["id"],
                        "content": observation,
                    }
                )

        if use_responses_api:
            resp_input = tool_outputs + injected_tool_messages

        # ── process pending injections from after_tool ──
        if ctx._pending_injections:
            inj = ctx._pending_injections[0]
            inj_name, inj_args = inj["name"], inj.get("args", {})
            ctx._in_injected_call = True
            before_tool_seq = ctx._tool_seq
            inj_error = False
            try:
                if (
                    completion_tool
                    and inj_name != completion_tool
                    and (is_finalization or ctx.remaining_tool_calls <= 1)
                ):
                    inj_result = (
                        "Tool execution budget exhausted for exploratory calls. "
                        f"The remaining execution is reserved for {completion_tool}. "
                        f"Call {completion_tool} with the final answer now."
                    )
                    trace.event(
                        "tool_execution_reserved",
                        turn=turn,
                        requested_tool=inj_name,
                        reserved_for=completion_tool,
                        injected=True,
                    )
                elif not completion_tool and ctx.remaining_tool_calls <= 0:
                    inj_result = (
                        "Tool execution budget exhausted. Provide your best final "
                        "answer as plain text now; do not call any more tools."
                    )
                    trace.event(
                        "tool_execution_reserved",
                        turn=turn,
                        requested_tool=inj_name,
                        reserved_for="final_text_answer",
                        injected=True,
                    )
                else:
                    inj_result = await _dispatch(inj_name, inj_args, ctx)
            except Exception as e:
                inj_result = f"injected tool error: {e}"
                inj_error = True
                trace.event("injection_error", tool=inj_name, error=str(e))
            finally:
                ctx._in_injected_call = False
                ctx._pending_injections.clear()
            inj_metadata = {}
            if ctx.tool_history and ctx.tool_history[-1].seq > before_tool_seq:
                inj_metadata = copy.deepcopy(ctx.tool_history[-1].result_metadata)
            trace.event(
                "tool_call",
                turn=turn,
                tool=inj_name,
                args=inj_args,
                result=inj_result,
                injected=True,
                result_metadata=inj_metadata,
                search=ctx.search_calls,
                read=ctx.read_calls,
            )
            inj_observation = format_tool_observation(
                inj_name, inj_args, inj_result, is_error=inj_error
            )
            inj_msg = {
                "role": "user",
                "content": (
                    "Runtime middleware executed an additional tool call.\n"
                    + inj_observation
                ),
            }
            if use_responses_api:
                resp_input.append(inj_msg)
            else:
                messages.append(inj_msg)
            ctx._injections_count += 1

        if ctx._completion_tool_called and ctx.state.get("completion_answer"):
            answer = str(ctx.state.get("completion_answer") or "")
            stop_reason = "completed"
            trace.event(
                "completion_tool_called",
                turn=turn,
                answer_length=len(answer),
            )
            break

        if ctx._stall_nudge_pending:
            nudge = ctx._stall_nudge_pending
            ctx._stall_nudge_pending = ""
            ctx._stall_nudges += 1
            _append_user_nudge(messages, resp_input, use_responses_api, nudge)
            trace.event(
                "stall_nudge",
                turn=turn,
                count=ctx._stall_nudges,
                nudge=nudge,
            )

    # ------------------------------------------------------------------
    # Strip residual tool-call tokens (e.g. DeepSeek DSML markers)
    # ------------------------------------------------------------------
    def _clean_answer(text: str) -> str:
        return re.sub(
            r"<｜｜DSML｜｜tool_calls>.*?(?:</｜｜DSML｜｜tool_calls>|\Z)",
            "",
            text,
            flags=re.DOTALL,
        ).strip()

    answer = _clean_answer(answer)
    needs_forced_answer = not answer and not stop_reason.startswith("llm_error")

    # ------------------------------------------------------------------
    # Final completion turn for runs that ended without complete_task
    # ------------------------------------------------------------------
    if (
        needs_forced_answer
        and completion_tool
        and not ctx._completion_tool_called
    ):
        forced_prompt = (
            "The run has ended and no exploratory tool executions remain. "
            f"You must call {completion_tool} now with the final verified answer "
            "for the original question. Do not call any other tool and do not "
            "describe the answer without calling the tool. If you are missing "
            "evidence, give your best answer and note the uncertainty in the "
            "answer argument."
        )
        if use_responses_api:
            forced_tc = "required" if completion_only_responses else "none"
            forced_tools = completion_only_responses or None
        else:
            forced_tc = (
                {"type": "function", "function": {"name": completion_tool}}
                if completion_only_chat
                else "none"
            )
            forced_tools = completion_only_chat or None

        for _attempt in range(1, llm.LLM_MAX_RETRIES + 1):
            try:
                request_started = time.monotonic()
                if use_responses_api:
                    forced_input = (
                        response_history
                        + resp_input
                        + [{"role": "user", "content": forced_prompt}]
                    )
                    resp = await llm.responses(
                        forced_input,
                        model=model,
                        instructions=bundle.system_prompt,
                        tools=forced_tools,
                        tool_choice=forced_tc,
                        reasoning=reasoning_cfg,
                        session_id=responses_session_id,
                        max_output_tokens=_max_output_tokens(),
                    )
                    content, _, function_calls = llm.extract_responses_output(resp)
                    forced_tc_list = [
                        _chat_tool_call_to_common(
                            _responses_call_to_chat_tool_call(fc)
                        )
                        for fc in function_calls
                    ]
                else:
                    forced_messages = messages + [
                        {"role": "user", "content": forced_prompt}
                    ]
                    resp = await llm.chat(
                        forced_messages,
                        model=model,
                        tools=forced_tools,
                        tool_choice=forced_tc,
                        max_tokens=_max_output_tokens(),
                    )
                    msg = resp.choices[0].message if resp.choices else None
                    content = getattr(msg, "content", "") or ""
                    forced_tc_list = [
                        _chat_tool_call_to_common(tc)
                        for tc in (getattr(msg, "tool_calls", None) or [])
                    ]
                usage = {
                    "role": "forced_answer",
                    "turn": last_turn + 1,
                    "model": model,
                    "call_id": getattr(resp, "id", None),
                    "latency_seconds": time.monotonic() - request_started,
                    "usage": llm.usage_dict(resp),
                }
                ctx.model_usage.append(usage)
                trace.event("model_usage", **usage)
                failure = llm.response_error(resp, responses_api=use_responses_api)
                if failure:
                    stop_reason = f"llm_error: {failure}"
                    trace.event("llm_error", turn=last_turn + 1, error=failure)
                    break

                if use_responses_api:
                    messages.append(
                        _middleware_assistant_message(content, forced_tc_list)
                    )
                elif msg is not None:
                    messages.append(_serialize_assistant(msg))

                forced_completed = False
                for tc in forced_tc_list:
                    name = tc["name"]
                    try:
                        args = json.loads(tc["arguments"])
                    except json.JSONDecodeError:
                        args = {}
                    before_tool_seq = ctx._tool_seq
                    tool_error = False
                    if name == completion_tool:
                        try:
                            result = await _dispatch(name, args, ctx)
                        except Exception as e:
                            result = f"tool error: {e}"
                            tool_error = True
                    else:
                        result = (
                            "No tool executions remain. Only "
                            f"{completion_tool} is available. Call "
                            f"{completion_tool} with the final answer now."
                        )
                    observation = format_tool_observation(
                        name, args, result, is_error=tool_error
                    )
                    result_metadata = {}
                    if ctx.tool_history and ctx.tool_history[-1].seq > before_tool_seq:
                        result_metadata = copy.deepcopy(
                            ctx.tool_history[-1].result_metadata
                        )
                    trace.event(
                        "tool_call",
                        turn=last_turn + 1,
                        tool=name,
                        args=args,
                        result=result,
                        result_metadata=result_metadata,
                        search=ctx.search_calls,
                        read=ctx.read_calls,
                    )
                    messages.append(
                        {
                            "role": "tool",
                            "tool_call_id": tc["id"],
                            "content": observation,
                        }
                    )
                    if ctx._completion_tool_called:
                        answer = str(ctx.state.get("completion_answer") or "")
                        stop_reason = "completed"
                        trace.event(
                            "forced_completion_tool_called",
                            turn=last_turn + 1,
                            answer_length=len(answer),
                        )
                        forced_completed = True
                        break
                if forced_completed:
                    break
                if content and not forced_tc_list:
                    answer = _clean_answer(content)
                    stop_reason = "no_tool_calls"
                    trace.event(
                        "forced_answer", stop_reason=stop_reason, length=len(answer)
                    )
                    break
            except Exception as e:
                if llm.is_fatal_api_error(e):
                    break
                if _attempt < llm.LLM_MAX_RETRIES:
                    await asyncio.sleep(2**_attempt)

    needs_forced_answer = not answer and not stop_reason.startswith("llm_error")

    # ------------------------------------------------------------------
    # Forced text answer for non-normal exits
    # ------------------------------------------------------------------
    if needs_forced_answer:
        forced_prompt = (
            "You have used all available turns. No more tool calls are allowed. "
            "Do NOT output any tool-call markup or XML tags. "
            "Provide your best final answer to the original question now "
            "as plain text, citing source URLs inline. "
            "If the evidence you gathered is insufficient, give your best "
            "guess and explicitly note the uncertainty."
        )
        for _attempt in range(1, llm.LLM_MAX_RETRIES + 1):
            try:
                request_started = time.monotonic()
                if use_responses_api:
                    forced_input = (
                        response_history
                        + resp_input
                        + [{"role": "user", "content": forced_prompt}]
                    )
                    resp = await llm.responses(
                        forced_input,
                        model=model,
                        instructions=bundle.system_prompt,
                        tools=None,
                        tool_choice="none",
                        reasoning=reasoning_cfg,
                        session_id=responses_session_id,
                        max_output_tokens=_max_output_tokens(),
                    )
                    forced_content, _, _ = llm.extract_responses_output(resp)
                else:
                    forced_messages = messages + [
                        {"role": "user", "content": forced_prompt}
                    ]
                    resp = await llm.chat(
                        forced_messages,
                        model=model,
                        tools=None,
                        tool_choice="none",
                        max_tokens=_max_output_tokens(),
                    )
                    forced_content = (
                        resp.choices[0].message.content if resp.choices else ""
                    )
                usage = {
                    "role": "forced_answer",
                    "turn": last_turn + 1,
                    "model": model,
                    "call_id": getattr(resp, "id", None),
                    "latency_seconds": time.monotonic() - request_started,
                    "usage": llm.usage_dict(resp),
                }
                ctx.model_usage.append(usage)
                trace.event("model_usage", **usage)
                forced = _clean_answer(forced_content or "")
                messages.extend(
                    [
                        {"role": "user", "content": forced_prompt},
                        {"role": "assistant", "content": forced},
                    ]
                )
                failure = llm.response_error(resp, responses_api=use_responses_api)
                if failure:
                    stop_reason = f"llm_error: {failure}"
                    trace.event("llm_error", turn=last_turn + 1, error=failure)
                    break
                if forced:
                    answer = forced
                trace.event(
                    "forced_answer", stop_reason=stop_reason, length=len(forced)
                )
                break
            except Exception as e:
                if llm.is_fatal_api_error(e):
                    break
                if _attempt < llm.LLM_MAX_RETRIES:
                    await asyncio.sleep(2**_attempt)

    if not answer:
        answer = "(no answer produced)"
        if not stop_reason.startswith("llm_error"):
            stop_reason = "llm_error: model returned no final answer text"

    if not stop_reason.startswith("llm_error"):
        stop_reason = "completed"

    trace.save_answer(answer)
    summary = {
        "question": question,
        "llm_config": llm_config,
        "stop_reason": stop_reason,
        "turns": last_turn,
        "search_calls": ctx.search_calls,
        "read_calls": ctx.read_calls,
        "run_dir": str(trace.dir),
        "workspace": str(bundle.root),
        "side_llm_calls": ctx._side_llm_calls,
        "unique_urls_searched": len(set(u for sr in ctx.searches for u in sr.urls)),
        "unique_urls_read": len(set(r.url for r in ctx.reads)),
        "read_failures": sum(1 for r in ctx.reads if not r.success),
        "tool_skips": ctx._tool_skips,
        "tool_redirects": ctx._tool_redirects,
        "injections_count": ctx._injections_count,
        "final_continues": ctx._final_continues,
        "tool_calls_executed": ctx._tool_seq,
        "stall_nudges": ctx._stall_nudges,
        "length_retry_used": ctx._length_retry_used,
        "completion_tool": completion_tool,
        "usage": ctx.model_usage,
    }
    trace.save_summary(summary)
    trace.event("run_end", **summary)
    trace.close()

    return trace.redact({"answer": answer, "messages": messages, **summary})

