"""
Workspace-aware ReAct loop.

The kernel:
  - Loads a workspace (agent.yaml + prompts + tool descriptions + extras).
  - Runs a ReAct loop with a budget (max_turns).
  - Dispatches tool calls: built-in (web_search/read_url)
    OR workspace-provided (workspace/tools/<name>.py).
  - Runs middleware hooks around each LLM turn and each tool call.

Built-in tool implementations live here; new tools are added by the proposer
in the workspace, NOT by editing this file.
"""

from __future__ import annotations

import ast
import asyncio
import copy
import json
import logging
import os
import re
import time
import uuid
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from types import SimpleNamespace
from typing import Any

from . import llm, reader
from . import web_config as web_settings
from . import workspace as ws_mod
from .tool_result import ToolResult, format_tool_observation
from .tools import web_search_structured
from .trace import TraceWriter
from .workspace import WorkspaceBundle

logger = logging.getLogger(__name__)


# ---------------------------------------------------------------------------
# Final-answer guard: reject turns whose text is really unexecuted tool-call
# markup rather than a plain final answer.
# ---------------------------------------------------------------------------

_TOOL_CALL_MARKUP_RE = re.compile(
    r"<\s*(?:"
    r"\|?DSML\|?\s*(?:tool_calls?|invoke|function_calls?)\b"
    r"|invoke\b"
    r"|function_calls?\b"
    r"|tool_calls?\b"
    r"|antml:invoke\b"
    r")",
    re.IGNORECASE,
)

_LEGACY_TOOL_CALL_MARKUP_RES = (
    re.compile(r"\bfunction_call\s*[:(=]", re.IGNORECASE),
    re.compile(r"""[\'"]function_call[\'"]\s*:\s*\{""", re.IGNORECASE),
    re.compile(r"\btool_calls?\s*:\s*[\[{]", re.IGNORECASE),
    re.compile(r"""[\'"]tool_calls?[\'"]\s*:\s*[\[{]""", re.IGNORECASE),
)


def _contains_unexecuted_tool_call_markup(text: str) -> bool:
    """Return True when *text* looks like tool-call syntax, not a final answer."""
    if not text:
        return False
    # DeepSeek DSML uses the fullwidth vertical bar (U+FF5C); normalize it so
    # one regex can handle both <DSML ...> and <｜DSML｜...> spellings.
    normalized = text.replace("｜", "|")
    if _TOOL_CALL_MARKUP_RE.search(normalized):
        return True
    return any(pattern.search(text) for pattern in _LEGACY_TOOL_CALL_MARKUP_RES)


# ---------------------------------------------------------------------------
# Runtime context — passed to middleware hooks and workspace tools
# ---------------------------------------------------------------------------


@dataclass
class SearchRecord:
    idx: int
    query: str
    turn: int
    items: list
    urls: list


@dataclass
class ReadRecord:
    idx: int
    url: str
    focus: str
    turn: int
    success: bool
    failure_type: str | None
    artifact_path: str | None
    content_preview: str


@dataclass
class ToolCallRecord:
    seq: int
    requested_name: str
    requested_args: dict
    executed_name: str
    executed_args: dict
    turn: int
    result_preview: str
    result_metadata: dict = field(default_factory=dict)
    action: str = "executed"
    source: str = "model"


@dataclass
class Context:
    workspace: WorkspaceBundle
    trace: TraceWriter
    working_dir: Path = field(default_factory=Path.cwd)
    # ── identity / config ──
    question: str = ""
    run_id: str = ""
    run_dir: str = ""
    model: str = ""
    max_turns: int = 0
    # ── counters ──
    search_calls: int = 0
    read_calls: int = 0
    # ── structured history ──
    searches: list = field(default_factory=list)
    reads: list = field(default_factory=list)
    tool_history: list = field(default_factory=list)
    current_turn_calls: list = field(default_factory=list)
    # ── middleware state ──
    sub_agents: dict[str, Any] = field(default_factory=dict)
    state: dict = field(default_factory=lambda: defaultdict(dict))
    memory: list = field(default_factory=list)
    # ── internal ──
    _current_turn: int = 0
    _tool_seq: int = 0
    _side_llm_calls: int = 0
    _side_llm_max: int = 20
    _in_injected_call: bool = False
    _pending_injections: list = field(default_factory=list)
    _tool_skips: int = 0
    _tool_redirects: int = 0
    _injections_count: int = 0
    _final_continues: int = 0
    _final_continue_max: int = 3
    # ── tool execution budget / finalization / stall detection ──
    max_tool_calls: int = 0
    _completion_tool: str = ""
    _completion_tool_called: bool = False
    _length_retry_used: bool = False
    # ── context management (AppWorld prerequisites / persistent status) ──
    _prereq_supervisor_credentials: bool = False
    _prereq_app_logins: dict[str, str] = field(default_factory=dict)
    _stall_signature_counts: dict = field(default_factory=lambda: defaultdict(int))
    _last_tool_signature: str = ""
    _introspection_streak: int = 0
    _stall_nudges: int = 0
    _stall_nudge_pending: str = ""
    model_usage: list = field(default_factory=list)

    @property
    def turn(self) -> int:
        return self._current_turn

    @property
    def elapsed_s(self) -> float:
        return round(time.time() - self.trace._t0, 1)

    @property
    def remaining_turns(self) -> int:
        return max(0, self.max_turns - self._current_turn)

    @property
    def tool_calls_executed(self) -> int:
        return self._tool_seq

    @property
    def remaining_tool_calls(self) -> int:
        if self.max_tool_calls <= 0:
            return max(0, (self.max_turns * 2) - self._tool_seq)
        return max(0, self.max_tool_calls - self._tool_seq)

    async def side_text(
        self, prompt: str, *, purpose: str, max_tokens: int = 500
    ) -> str | None:
        if self._side_llm_calls >= self._side_llm_max:
            self.trace.event("side_llm_budget_exceeded", budget=self._side_llm_max)
            return None
        self._side_llm_calls += 1
        capped = min(max_tokens, 500)
        started = time.monotonic()
        try:
            result, response = await llm.text(
                prompt,
                model=llm.SIDE_MODEL,
                max_tokens=capped,
                _return_response=True,
            )
        except Exception as e:
            self.trace.event(
                "side_llm_error",
                call_n=self._side_llm_calls,
                purpose=purpose,
                error=str(e),
            )
            return None
        self.trace.event(
            "side_llm",
            call_n=self._side_llm_calls,
            purpose=purpose,
            prompt_len=len(prompt),
            result_len=len(result),
        )
        usage = {
            "role": "side",
            "call_n": self._side_llm_calls,
            "model": llm.SIDE_MODEL,
            "call_id": getattr(response, "id", None),
            "latency_seconds": time.monotonic() - started,
            "usage": llm.usage_dict(response),
        }
        self.model_usage.append(usage)
        self.trace.event("model_usage", **usage)
        return result


# ---------------------------------------------------------------------------
# Built-in tool dispatch
# ---------------------------------------------------------------------------


def _serialize_assistant(msg) -> dict:
    """Convert an LLM response Message into a plain dict for the next request.

    Preserves `reasoning_content` for models that require it on tool round-trips. Strips
    fields the API rejects on input (`refusal`, `audio`, etc.)."""
    if hasattr(msg, "model_dump"):
        d = msg.model_dump(exclude_none=True)
    elif hasattr(msg, "dict"):
        d = msg.dict(exclude_none=True)
    else:
        d = {"role": getattr(msg, "role", "assistant")}
        if getattr(msg, "content", None) is not None:
            d["content"] = msg.content
        if getattr(msg, "reasoning_content", None) is not None:
            d["reasoning_content"] = msg.reasoning_content
        tcs = getattr(msg, "tool_calls", None)
        if tcs:
            d["tool_calls"] = [
                {
                    "id": tc.id,
                    "type": getattr(tc, "type", "function"),
                    "function": {
                        "name": tc.function.name,
                        "arguments": tc.function.arguments,
                    },
                }
                for tc in tcs
            ]
    if "tool_calls" in d and "content" not in d:
        d["content"] = ""
    for k in (
        "function_call",
        "audio",
        "annotations",
        "refusal",
        "provider_specific_fields",
    ):
        d.pop(k, None)
    return d


def _obj_get(obj: Any, key: str, default: Any = None) -> Any:
    if isinstance(obj, dict):
        return obj.get(key, default)
    return getattr(obj, key, default)


def _make_chat_tool_call(call_id: str, name: str, arguments: str):
    """Create a chat-completions-shaped tool call object."""
    return SimpleNamespace(
        id=call_id,
        type="function",
        function=SimpleNamespace(name=name, arguments=arguments),
    )


def _responses_call_to_chat_tool_call(fc: Any):
    call_id = (
        _obj_get(fc, "call_id")
        or _obj_get(fc, "id")
        or _obj_get(fc, "tool_call_id")
        or ""
    )
    name = _obj_get(fc, "name") or _obj_get(_obj_get(fc, "function", {}), "name") or ""
    arguments = (
        _obj_get(fc, "arguments")
        or _obj_get(_obj_get(fc, "function", {}), "arguments")
        or "{}"
    )
    if not isinstance(arguments, str):
        arguments = json.dumps(arguments, ensure_ascii=False)
    return _make_chat_tool_call(call_id, name, arguments)


def _chat_tool_call_to_common(tc: Any, *, injected: bool = False) -> dict:
    fn = _obj_get(tc, "function", {}) or {}
    args = _obj_get(fn, "arguments", "{}") or "{}"
    if not isinstance(args, str):
        args = json.dumps(args, ensure_ascii=False)
    out = {
        "id": _obj_get(tc, "id", "") or "",
        "name": _obj_get(fn, "name", "") or "",
        "arguments": args,
    }
    if injected:
        out["injected"] = True
    return out


# ---------------------------------------------------------------------------
# Budget / finalization / stall helpers
# ---------------------------------------------------------------------------

_LENGTH_RETRY_EXTRA_TOKENS = 4096
_LENGTH_RETRY_CONTEXT_TAIL = 8
_FINALIZATION_MAX_TURNS = 2
_COMPLETION_ANSWER_KEYS = (
    "answer",
    "final_answer",
    "completed_answer",
    "task_answer",
    "content",
    "result",
    "response",
    "text",
    "value",
    "output",
    "final",
)
_STALL_SAME_SIGNATURE_LIMIT = 3
_STALL_INTROSPECTION_STREAK_LIMIT = 3
_INTROSPECTION_NAME_RE = re.compile(
    r"(^|_)(help|limit|limits|check_limit|check_limits|print|list|show|describe|docs|introspect|inspect|status|debug|env|whoami|pwd|ls|cat)(_|$)",
    re.IGNORECASE,
)
_INTROSPECTION_CODE_RE = re.compile(
    r"__(dict|class|module|name)__|\b(help|dir|type|pprint|repr|globals|locals|vars)\s*\(",
    re.IGNORECASE,
)
_LIMIT_CHECK_CODE_RE = re.compile(
    r"\bapis\.(check_limit|check_limits|get_limit|get_limits|has_limit|rate_limit|limits?)\s*\(",
    re.IGNORECASE,
)


def _completion_tool_name(bundle) -> str:
    names = list(bundle.tool_names or [])
    for exact in ("complete_task", "final_answer"):
        if exact in names:
            return exact
    for name in names:
        if "complete" in name:
            return name
    for name in names:
        if "supervisor" in name:
            return name
    for exact in ("finish", "submit"):
        if exact in names:
            return exact
    for name in names:
        if "submit" in name or "finish" in name:
            return name
    # AppWorld-style workspaces expose supervisor APIs inside Python code rather
    # than as a separate runtime tool. The generic executor is the only tool that
    # can submit supervisor.complete_task, so reserve/force that tool for the
    # finalization stage while using the code-level detector for the real call.
    if "appworld_execute" in names:
        return "appworld_execute"
    return ""


def _completion_only_schemas(bundle, completion_tool: str) -> list[dict]:
    if not completion_tool:
        return []
    return [
        schema
        for schema in bundle.tool_schemas
        if ((schema.get("function") or {}).get("name")) == completion_tool
    ]


def _is_supervisor_complete_call_node(func: ast.AST) -> bool:
    if not isinstance(func, ast.Attribute) or func.attr != "complete_task":
        return False
    value = func.value
    if isinstance(value, ast.Name) and value.id == "supervisor":
        return True
    return (
        isinstance(value, ast.Attribute)
        and value.attr == "supervisor"
        and isinstance(value.value, ast.Name)
        and value.value.id == "apis"
    )


def _extract_completion_answer(args: dict) -> str:
    """Best-effort extraction of the answer supplied to a completion call.

    Handles both explicit completion tools (which usually carry an ``answer``
    key) and AppWorld-style ``appworld_execute`` calls, where the answer is a
    keyword argument inside a ``supervisor.complete_task(...)`` Python snippet.
    """
    if not isinstance(args, dict):
        return ""
    for key in _COMPLETION_ANSWER_KEYS:
        value = args.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
        if isinstance(value, dict):
            nested = _extract_completion_answer(value)
            if nested:
                return nested
    code = args.get("code")
    if isinstance(code, str):
        try:
            tree = ast.parse(code)
        except SyntaxError:
            tree = None
        if tree is not None:
            for node in ast.walk(tree):
                if not isinstance(node, ast.Call):
                    continue
                func = node.func
                if not _is_supervisor_complete_call_node(func):
                    continue
                for kw in node.keywords:
                    if kw.arg in _COMPLETION_ANSWER_KEYS and isinstance(kw.value, ast.Constant):
                        value = kw.value.value
                        if isinstance(value, str) and value.strip():
                            return value.strip()
                for kw in node.keywords:
                    if kw.arg == "status" and isinstance(kw.value, ast.Constant):
                        status = kw.value.value
                        if isinstance(status, str) and status.strip():
                            return status.strip()
    return ""


def _is_budget_exhausted_failure(failure: str | None) -> bool:
    if not failure:
        return False
    return (
        "length" in failure
        or "max_output_tokens" in failure
        or "output budget exhausted" in failure
    )


def _max_output_tokens(*, retry: bool = False) -> int:
    base = int(getattr(llm, "MAX_TOKENS", 4096) or 4096)
    if getattr(llm, "REASONING_EFFORT", "") and base < 8192:
        # Reasoning tokens count against the same output budget. Ensure the
        # budget is large enough that reasoning plus a final tool/answer can fit.
        base = 8192
    if retry:
        base += _LENGTH_RETRY_EXTRA_TOKENS
    return base


def _recent_tool_summary(ctx: Context, limit: int = _LENGTH_RETRY_CONTEXT_TAIL) -> str:
    if not ctx.tool_history:
        return ""
    recent = ctx.tool_history[-limit:]
    lines = []
    for rec in recent:
        args = json.dumps(rec.requested_args, ensure_ascii=False, default=str)
        lines.append(
            f"- {rec.executed_name}({args}) -> {rec.result_preview or '(no output)'}"
        )
    return "Recent tool activity:\n" + "\n".join(lines)


def _length_retry_nudge(ctx: Context) -> str:
    instruction = _completion_instruction(ctx)
    lines = [
        "Your previous model output exhausted its token budget before producing "
        "a usable next action or final answer.",
        "Do not repeat prior reasoning or re-read long documents. Using the "
        "original question and the recent activity below, decide the single "
        "next step.",
    ]
    if instruction != "provide the final answer as plain text":
        lines.append(
            f"If you have enough evidence, {instruction} now with the "
            "final verified answer. If you still need one critical piece of "
            "evidence, emit exactly one concise tool call for it."
        )
    else:
        lines.append(
            "If you still need one critical piece of evidence, emit exactly one "
            "concise tool call for it. Otherwise, provide your best final answer "
            "now as plain text."
        )
    if "appworld_execute" in ctx.workspace.tool_names:
        lines.append(
            "If you are unsure which API to call, use appworld_execute once with "
            "apis.api_docs to look it up."
        )
    return " ".join(lines)


def _reduced_chat_messages(ctx: Context, nudge: str) -> list[dict]:
    system = {"role": "system", "content": ctx.workspace.system_prompt}
    parts = [ctx.question]
    summary = _recent_tool_summary(ctx)
    if summary:
        parts.append(summary)
    parts.append(nudge)
    return [system, {"role": "user", "content": "\n\n".join(parts)}]


def _reduced_responses_input(ctx: Context, nudge: str) -> list[dict]:
    parts = [ctx.question]
    summary = _recent_tool_summary(ctx)
    if summary:
        parts.append(summary)
    parts.append(nudge)
    return [{"role": "user", "content": "\n\n".join(parts)}]


def _is_introspection_tool(name: str, args: dict, ctx: Context | None = None) -> bool:
    if (
        ctx is not None
        and "appworld_execute" in ctx.workspace.tool_names
        and _INTROSPECTION_NAME_RE.search(name)
    ):
        return True
    if name == "appworld_execute":
        code = str(args.get("code") or "")
        if not code.strip():
            return False
        if re.search(r"\bapis\.", code):
            return bool(_LIMIT_CHECK_CODE_RE.search(code))
        if _INTROSPECTION_CODE_RE.search(code):
            return True
    return False


def _nudge_for_stall(ctx: Context, name: str, args: dict) -> str:
    instruction = _completion_instruction(ctx)
    has_appworld = "appworld_execute" in ctx.workspace.tool_names
    if instruction != "provide the final answer as plain text":
        if has_appworld:
            return (
                f"You are making repeated non-progress tool calls ({name}). "
                "Stop introspecting or re-checking limits. If you are unsure how "
                "to perform the required action, look up the correct API with "
                "apis.api_docs, then execute it and verify the result. As soon as "
                f"you have a verified answer, {instruction} with that "
                "answer. Do not call any other introspection or limit-checking "
                "tools."
            )
        return (
            f"You are making repeated non-progress tool calls ({name}). Stop "
            "introspecting or re-checking limits. If you need API details, consult "
            "the API documentation; otherwise use the evidence you already have. "
            f"When you have a verified answer, {instruction} with it."
        )
    if has_appworld:
        return (
            f"You are making repeated non-progress tool calls ({name}). Stop "
            "introspecting or re-checking limits. If you are unsure how to "
            "perform the required action, use appworld_execute once with "
            "apis.api_docs to look up the correct API, then execute it and "
            "verify the result. Then provide the final answer."
        )
    return (
        f"You are making repeated non-progress tool calls ({name}). Stop "
        "introspecting or re-checking limits. Use the evidence you already have "
        "and provide the final answer now. If you need API details, consult the "
        "API documentation first."
    )


def _append_user_nudge(messages, resp_input, use_responses_api: bool, nudge: str) -> None:
    if not nudge:
        return
    msg = {"role": "user", "content": nudge}
    if use_responses_api:
        resp_input.append(msg)
    else:
        messages.append(msg)


def _budget_warning(ctx: Context) -> str:
    """Return a short, low-budget instruction for the model, or "".

    The final tool execution is reserved for the workspace completion action when
    one exists. Surface that reservation before the LLM call so the model has a
    chance to finish cleanly instead of hitting the hard execution cap.
    """
    remaining = ctx.remaining_tool_calls
    completion_tool = getattr(ctx, "_completion_tool", "") or ""
    instruction = _completion_instruction(ctx)
    if completion_tool or _is_appworld_environment(ctx):
        if remaining <= 0:
            return (
                "No exploratory tool executions remain. The only available "
                f"terminal action is to {instruction}. Do so now with the final "
                "verified answer and do not call any other tool."
            )
        if remaining == 1:
            return (
                f"Only one tool execution remains and it is reserved for the "
                f"terminal action: {instruction}. Do so now with the final "
                "verified answer. Do not call any other tool."
            )
        if remaining == 2:
            return (
                f"Only two tool executions remain, and the final one is "
                f"reserved for the terminal action ({instruction}). If you still "
                "need one critical piece of evidence, use at most one exploratory "
                "tool call now; otherwise perform the terminal action now."
            )
    else:
        if remaining <= 0:
            return (
                "No tool executions remain. Provide your best final answer now "
                "as plain text. Do not call any more tools."
            )
        if remaining == 1:
            return (
                "Only one tool execution remains. Use it only if it is essential "
                "for the final answer; otherwise provide your final answer now "
                "as plain text."
            )
    return ""


# ---------------------------------------------------------------------------
# AppWorld-aware completion / prerequisite tracking
# ---------------------------------------------------------------------------

_COMPLETION_TOOL_CANDIDATES = ("supervisor.complete_task", "complete_task")
_APP_LOGIN_RE = re.compile(r"\b([A-Za-z_]\w*)\s*\.\s*login\s*\(", re.IGNORECASE)
_SUPERVISOR_CREDENTIAL_RE = re.compile(
    r"\b(?:supervisor\s*\.\s*(?:get_credentials|get_app_credentials|"
    r"list_credentials|get_credential|get_secret)\s*\(|"
    r"get_supervisor_credentials\s*\(|supervisor\s*\.\s*credentials\b)",
    re.IGNORECASE,
)
_COMPLETION_CALL_RE = re.compile(
    r"\b(?:supervisor\s*\.\s*complete_task|complete_task)\s*\(", re.IGNORECASE
)
_LOGIN_FAILURE_RE = re.compile(
    r"\b(?:failed?|failure|incorrect|invalid|denied|unauthorized|"
    r"traceback|exception|wrong\s+password)\b",
    re.IGNORECASE,
)


def _is_appworld_environment(ctx: Context) -> bool:
    """True when the workspace exposes AppWorld-style execute/supervisor APIs."""
    for name in getattr(ctx.workspace, "tool_names", None) or []:
        lowered_name = name.lower()
        if "appworld" in lowered_name or "app_world" in lowered_name or "app world" in lowered_name:
            return True
    for schema in getattr(ctx.workspace, "tool_schemas", None) or []:
        if not isinstance(schema, dict):
            continue
        desc = (schema.get("function") or {}).get("description", "") or ""
        lowered = desc.lower()
        if "appworld" in lowered or "app world" in lowered or "supervisor" in lowered:
            return True
    return False


def _detect_completion_tool(ctx: Context) -> str | None:
    """Return a workspace terminal-completion tool name, if explicitly present."""
    tool_names = list(getattr(ctx.workspace, "tool_names", None) or [])
    for candidate in _COMPLETION_TOOL_CANDIDATES:
        if candidate in tool_names:
            return candidate
    for name in tool_names:
        if name.endswith("complete_task"):
            return name
    return None


def _detect_completion_signal(ctx: Context) -> str | None:
    """Return the terminal completion name to display/track for this workspace."""
    completion_name = _detect_completion_tool(ctx)
    if completion_name is not None:
        return completion_name
    if _is_appworld_environment(ctx):
        return "supervisor.complete_task"
    return None


def _code_like_text(args: dict | None) -> str:
    """Best-effort extraction of submitted code from a tool's arguments."""
    if not isinstance(args, dict):
        return ""
    code = args.get("code")
    if isinstance(code, str):
        return code
    parts: list[str] = []
    for key, value in args.items():
        if isinstance(value, str):
            parts.append(f"{key}: {value}")
    return "\n".join(parts)


def _code_contains_completion_call(code: str) -> bool:
    if not code:
        return False
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return bool(_COMPLETION_CALL_RE.search(code))
    return any(
        isinstance(node, ast.Call) and _is_supervisor_complete_call_node(node.func)
        for node in ast.walk(tree)
    )


def _tool_call_contains_completion(name: str, args: dict, ctx: Context) -> bool:
    """Return True when a tool call is the terminal completion action."""
    if ctx._completion_tool and name == ctx._completion_tool:
        if ctx._completion_tool == "appworld_execute":
            return _code_contains_completion_call(_code_like_text(args))
        return True
    if _is_appworld_environment(ctx) and name == "appworld_execute":
        return _code_contains_completion_call(_code_like_text(args))
    return False


def _completion_instruction(ctx: Context) -> str:
    if ctx._completion_tool == "appworld_execute":
        return "call appworld_execute with supervisor.complete_task(...)"
    if ctx._completion_tool:
        return f"call {ctx._completion_tool}"
    if _is_appworld_environment(ctx):
        return "call supervisor.complete_task(...) via appworld_execute"
    return "provide the final answer as plain text"


def _result_indicates_task_completed(result: str) -> bool:
    """Best-effort detection of an AppWorld task_completed flag."""
    if not result:
        return False
    try:
        data = json.loads(result)
    except (json.JSONDecodeError, TypeError):
        data = None
    if isinstance(data, dict) and data.get("task_completed") is True:
        return True
    return bool(re.search(r"\btask_completed\s*[:=]\s*true\b", result, re.IGNORECASE))


def _result_indicates_failure(result: str) -> bool:
    """Best-effort failure detection for AppWorld tool output strings."""
    if not result:
        return False
    try:
        data = json.loads(result)
    except (json.JSONDecodeError, TypeError):
        data = None
    if isinstance(data, dict):
        err = data.get("error") or data.get("exception")
        if (isinstance(err, str) and err.strip()) or err:
            return True
        if data.get("success") is False:
            return True
        output = data.get("output")
        if isinstance(output, str) and _LOGIN_FAILURE_RE.search(output):
            return True
    return bool(_LOGIN_FAILURE_RE.search(result))


def _observe_tool_result(
    ctx: Context,
    *,
    requested_name: str,
    requested_args: dict,
    executed_name: str,
    executed_args: dict,
    result: str,
    skipped: bool,
) -> None:
    """Update persistent context state after a tool result.

    Tracks AppWorld-style authentication prerequisites and records a successful
    terminal completion call exactly once. It never blocks a tool call; it only
    makes completion/prerequisite state visible on subsequent planning steps.
    """
    if skipped:
        return

    redirected = (
        requested_name != executed_name or requested_args != executed_args
    )

    if _is_appworld_environment(ctx):
        code = _code_like_text(executed_args)
        if not redirected and not code:
            code = _code_like_text(requested_args)
        if code:
            if _SUPERVISOR_CREDENTIAL_RE.search(code):
                ctx._prereq_supervisor_credentials = not _result_indicates_failure(
                    result
                )
            for match in _APP_LOGIN_RE.finditer(code):
                app = match.group(1).lower()
                if app in {"supervisor", "system", "sys", "os"}:
                    continue
                if _result_indicates_failure(result):
                    ctx._prereq_app_logins[app] = "login failed"
                else:
                    ctx._prereq_app_logins[app] = "logged in"

    completion_observed = _tool_call_contains_completion(
        executed_name, executed_args, ctx
    )
    if not redirected:
        completion_observed = completion_observed or _tool_call_contains_completion(
            requested_name, requested_args, ctx
        )
    if (
        _is_appworld_environment(ctx)
        and not completion_observed
        and _result_indicates_task_completed(result)
    ):
        completion_observed = True

    if completion_observed and not ctx._completion_tool_called:
        if _result_indicates_failure(result):
            ctx.trace.event(
                "completion_tool_error",
                tool=executed_name,
                result_preview=result[:200],
            )
            return
        ctx._completion_tool_called = True
        answer = _extract_completion_answer(executed_args)
        if not answer:
            answer = _extract_completion_answer(requested_args)
        if not answer:
            answer = result.strip() or "completed"
        ctx.state["completion_answer"] = answer
        ctx.trace.event(
            "completion_tool_called",
            tool=executed_name,
            turn=ctx._current_turn,
            remaining=ctx.remaining_turns,
            answer_length=len(answer),
        )


def _prerequisite_checklist_text(ctx: Context) -> str:
    """Compact prerequisite status for AppWorld-style authentication setup."""
    if not _is_appworld_environment(ctx):
        return ""
    credential_state = (
        "retrieved" if ctx._prereq_supervisor_credentials else "NOT retrieved"
    )
    parts = [f"supervisor credentials: {credential_state}"]
    if ctx._prereq_app_logins:
        login_bits = [
            f"{app}: {state}"
            for app, state in sorted(ctx._prereq_app_logins.items())
        ]
        parts.append("app logins: " + "; ".join(login_bits))
        if all(state == "logged in" for state in ctx._prereq_app_logins.values()):
            parts.append("(observed prerequisites satisfied)")
        else:
            parts.append("(prerequisites INCOMPLETE)")
    else:
        parts.append("app logins: none observed")
        if ctx._prereq_supervisor_credentials:
            parts.append("(ensure every app required by the task is logged in)")
        else:
            parts.append("(prerequisites INCOMPLETE)")
    return "Prerequisites: " + " | ".join(parts) + "."


def _context_status_message(ctx: Context) -> dict | None:
    """Compact persistent status shown to the model before each planning step."""
    used = ctx._current_turn
    total = ctx.max_turns
    remaining = ctx.remaining_turns
    completion_name = _detect_completion_signal(ctx)
    instruction = _completion_instruction(ctx)

    parts = [
        f"[Runtime context] Interactions used: {used}/{total} ({remaining} remaining)."
    ]

    if completion_name is not None:
        called = "yes" if ctx._completion_tool_called else "no"
        parts.append(f"{completion_name} called: {called}.")
        if ctx._completion_tool_called:
            parts.append(
                "Task completion has already been recorded; do not call it again. "
                "Provide the final answer without further tool calls."
            )
        elif remaining <= 0:
            parts.append(
                "No tool-using interactions remain; provide the final answer now "
                f"or {instruction}."
            )
        elif remaining == 1:
            parts.append(
                f"This is the final tool-using interaction. If the task state is "
                f"satisfied and all prerequisites are met, {instruction} NOW and "
                "no other tools. Do not explore or verify further."
            )
        elif remaining <= 3:
            parts.append(
                f"Only {remaining} tool-using interactions remain. Complete "
                f"unfinished prerequisites immediately and {instruction} as soon "
                "as the task state is satisfied; do not spend interactions on "
                "extra verification."
            )
        else:
            parts.append(
                f"Once the task state is satisfied, stop additional exploration or "
                f"verification and {instruction}. The final LLM turn disables "
                "tool calls, so reserve the final tool-using interaction(s) for "
                "that terminal call."
            )
    elif remaining <= 0:
        parts.append(
            "No tool-using interactions remain; provide the final answer now."
        )
    elif remaining == 1:
        parts.append(
            "This is the final tool-using interaction; emit the terminal action or "
            "final answer now."
        )

    prerequisite_text = _prerequisite_checklist_text(ctx)
    if (
        prerequisite_text
        and completion_name is not None
        and not ctx._completion_tool_called
    ):
        parts.append(prerequisite_text)
        if remaining > 0 and "INCOMPLETE" in prerequisite_text:
            parts.append(
                f"Do not call {completion_name} until every required prerequisite "
                "is complete."
            )
        elif remaining > 0 and "ensure every app required" in prerequisite_text:
            parts.append(
                f"Before calling {completion_name}, ensure every app required by "
                "the task is logged in."
            )

    if len(parts) == 1:
        return None
    return {"role": "user", "content": " ".join(parts)}


def _combined_runtime_status(ctx: Context) -> dict | None:
    """One pre-turn status nudge merging context and tool-budget signals."""
    parts: list[str] = []
    context_msg = _context_status_message(ctx)
    if context_msg is not None:
        parts.append(context_msg["content"])
    budget_msg = _budget_warning(ctx)
    if budget_msg:
        parts.append(budget_msg)
    if not parts:
        return None
    return {"role": "user", "content": " ".join(parts)}


class _ResponsesMiddlewareAdapter:
    """Chat-like response facade for middleware on Responses API runs."""

    def __init__(
        self,
        raw: Any,
        content: str,
        reasoning: str,
        function_calls: list,
        *,
        original_call_ids: set[str] | None = None,
    ):
        self.raw_response = raw
        self._content = content or ""
        self._reasoning_content = reasoning or ""
        self._reasoning = reasoning or ""
        self._tool_calls = [
            _responses_call_to_chat_tool_call(fc) for fc in function_calls
        ]
        if original_call_ids is None:
            original_call_ids = {
                _obj_get(tc, "id", "") or "" for tc in self._tool_calls
            }
        self._original_call_ids = set(original_call_ids)
        self.choices = [
            SimpleNamespace(
                message=SimpleNamespace(
                    role="assistant",
                    content=self._content,
                    reasoning_content=self._reasoning_content,
                    tool_calls=self._tool_calls,
                ),
                finish_reason="tool_calls" if self._tool_calls else "stop",
            )
        ]

    @property
    def content(self) -> str:
        return self._content

    @content.setter
    def content(self, value: str | None) -> None:
        self._content = value or ""
        try:
            self.choices[0].message.content = self._content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning_content(self) -> str:
        return self._reasoning_content

    @reasoning_content.setter
    def reasoning_content(self, value: str | None) -> None:
        self._reasoning_content = value or ""
        try:
            self.choices[0].message.reasoning_content = self._reasoning_content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning(self) -> str:
        return self._reasoning

    @reasoning.setter
    def reasoning(self, value: str | None) -> None:
        self._reasoning = value or ""

    @property
    def tool_calls(self) -> list:
        return self._tool_calls

    @tool_calls.setter
    def tool_calls(self, value: list | None) -> None:
        self._tool_calls = list(value or [])
        try:
            self.choices[0].message.tool_calls = self._tool_calls
            self.choices[0].finish_reason = "tool_calls" if self._tool_calls else "stop"
        except (AttributeError, IndexError, TypeError):
            pass

    def sync_from_message(self) -> None:
        msg = self.choices[0].message
        msg_content = getattr(msg, "content", None)
        if msg_content is not None:
            self._content = msg_content
        elif getattr(self, "content", None) is not None:
            msg.content = self._content
        msg_reasoning = getattr(msg, "reasoning_content", None)
        if msg_reasoning is not None:
            self._reasoning_content = msg_reasoning
            self._reasoning = self._reasoning or msg_reasoning
        msg_tool_calls = getattr(msg, "tool_calls", None)
        self._tool_calls = list(msg_tool_calls or [])
        msg.tool_calls = self._tool_calls

    def common_tool_calls(self) -> list[dict]:
        self.sync_from_message()
        out: list[dict] = []
        for tc in self.tool_calls:
            call_id = _obj_get(tc, "id", "") or ""
            out.append(
                _chat_tool_call_to_common(
                    tc,
                    injected=call_id not in self._original_call_ids,
                )
            )
        return out


def _ensure_responses_adapter(
    response: Any,
    *,
    original_call_ids: set[str],
) -> _ResponsesMiddlewareAdapter:
    """Normalize middleware return values back into the Responses facade."""
    if isinstance(response, _ResponsesMiddlewareAdapter):
        return response

    choices = getattr(response, "choices", None)
    if choices:
        msg = choices[0].message
        adapter = _ResponsesMiddlewareAdapter(
            response,
            getattr(msg, "content", None) or getattr(response, "content", "") or "",
            getattr(msg, "reasoning_content", None)
            or getattr(response, "reasoning_content", None)
            or getattr(response, "reasoning", None)
            or "",
            [],
            original_call_ids=original_call_ids,
        )
        adapter.choices = choices
        adapter.sync_from_message()
        return adapter

    if getattr(response, "output", None) is not None:
        content, reasoning, function_calls = llm.extract_responses_output(response)
        return _ResponsesMiddlewareAdapter(
            response,
            content,
            reasoning,
            function_calls,
            original_call_ids=original_call_ids,
        )

    adapter = _ResponsesMiddlewareAdapter(
        response,
        getattr(response, "content", None) or "",
        getattr(response, "reasoning_content", None)
        or getattr(response, "reasoning", None)
        or "",
        [],
        original_call_ids=original_call_ids,
    )
    adapter.tool_calls = list(getattr(response, "tool_calls", None) or [])
    return adapter


def _middleware_message_key(msg: Any) -> str:
    try:
        return json.dumps(msg, ensure_ascii=False, sort_keys=True, default=str)
    except Exception:
        return repr(msg)


def _middleware_additions(before: list, after: list) -> list:
    """Return messages added by before_llm hooks, even if hooks copied lists."""
    remaining: dict[str, int] = {}
    for msg in before:
        key = _middleware_message_key(msg)
        remaining[key] = remaining.get(key, 0) + 1

    added = []
    for msg in after:
        key = _middleware_message_key(msg)
        if remaining.get(key, 0) > 0:
            remaining[key] -= 1
        else:
            added.append(msg)
    return added


def _responses_input_from_middleware_message(msg: Any) -> dict | None:
    role = _obj_get(msg, "role", "") or ""
    content = _obj_get(msg, "content", "") or ""
    if not content or role not in {"system", "developer", "user", "assistant"}:
        return None
    # Responses API already receives the main system prompt via instructions;
    # runtime middleware nudges are safest as developer messages.
    if role == "system":
        role = "developer"
    return {"role": role, "content": content}


def _middleware_assistant_message(content: str, tc_list: list[dict]) -> dict:
    msg = {"role": "assistant", "content": content or ""}
    if tc_list:
        msg["tool_calls"] = [
            {
                "id": tc["id"],
                "type": "function",
                "function": {
                    "name": tc["name"],
                    "arguments": tc["arguments"],
                },
            }
            for tc in tc_list
        ]
    return msg


async def _dispatch_builtin(name: str, args: dict, ctx: Context) -> str | None:
    """Returns a string result for built-ins; None if `name` is not built-in."""
    if name == "web_search":
        ctx.search_calls += 1
        query = (args.get("query") or "").strip()
        if not query:
            return "web_search requires a non-empty `query`."
        result_text, items = await web_search_structured(query)
        ctx.trace.save_search(ctx.search_calls, query, result_text)
        urls = [item["url"] for item in items]
        ctx.searches.append(
            SearchRecord(
                idx=ctx.search_calls,
                query=query,
                turn=ctx._current_turn,
                items=items,
                urls=urls,
            )
        )
        return result_text

    if name == "read_url":
        ctx.read_calls += 1
        url = (args.get("url") or "").strip()
        focus = (args.get("focus") or "").strip()
        if not url:
            return "read_url requires a non-empty `url`."
        page = await reader.read_url_with_raw(
            url,
            focus or "general relevance",
            extract_prompt=ctx.workspace.extract_prompt,
        )
        extracted = page["extracted"]
        artifact_path = ctx.trace.save_page(
            url, focus, extracted, raw_text=page.get("raw", "")
        )
        success = True
        failure_type = None
        if "[reader] fetch failed" in extracted:
            success, failure_type = False, "fetch_failed"
        elif "[reader] extract error" in extracted:
            success, failure_type = False, "extract_error"
        elif "[reader] no relevant content" in extracted:
            success, failure_type = False, "no_content"
        ctx.reads.append(
            ReadRecord(
                idx=ctx.read_calls,
                url=url,
                focus=focus,
                turn=ctx._current_turn,
                success=success,
                failure_type=failure_type,
                artifact_path=artifact_path,
                content_preview=extracted[:500],
            )
        )
        return extracted

    return None


def _normalize_tool_result(value: Any, ctx: Context, *, tool: str) -> tuple[str, dict]:
    """Normalize custom workspace tool returns into content + metadata."""
    if isinstance(value, ToolResult):
        metadata = value.metadata if isinstance(value.metadata, dict) else {}
        if value.metadata is not metadata:
            ctx.trace.event(
                "tool_result_warning", tool=tool, reason="metadata_not_dict"
            )
        return str(value.content), copy.deepcopy(metadata)
    if isinstance(value, str):
        return value, {}
    if value is None:
        ctx.trace.event("tool_result_warning", tool=tool, reason="none_return")
        return "", {}
    ctx.trace.event(
        "tool_result_warning",
        tool=tool,
        reason=f"unexpected_return_type: {type(value).__name__}",
    )
    return str(value), {}


async def _run_before_final_hooks(
    candidate: str, ctx: Context
) -> tuple[str, str, str | None]:
    """Run final-answer gates. Returns (action, answer, feedback)."""
    answer = candidate
    for mw in ctx.workspace.middlewares:
        hook = getattr(mw, "before_final", None)
        if not hook:
            continue
        try:
            ret = await hook(answer, ctx)
        except Exception as e:
            ctx.trace.event(
                "middleware_error", hook="before_final", mw=mw.name, error=str(e)
            )
            continue

        if ret is None:
            ctx.trace.event("before_final_accept", mw=mw.name, mode="implicit")
            continue
        if not isinstance(ret, dict):
            ctx.trace.event(
                "middleware_warning",
                hook="before_final",
                mw=mw.name,
                reason=f"unexpected_return_type: {type(ret).__name__}",
            )
            continue

        action = ret.get("action", "accept")
        if action == "accept":
            ctx.trace.event("before_final_accept", mw=mw.name, mode="explicit")
            continue

        if action == "replace":
            if "answer" not in ret:
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="replace_missing_answer",
                )
                continue
            answer = str(ret.get("answer") or "")
            ctx.trace.event("before_final_replace", mw=mw.name, length=len(answer))
            continue

        if action == "continue":
            feedback = ret.get("feedback")
            if not isinstance(feedback, str) or not feedback.strip():
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="continue_missing_feedback",
                )
                continue
            if ctx.remaining_turns <= 0:
                ctx.trace.event(
                    "before_final_continue_rejected", mw=mw.name, reason="last_turn"
                )
                return "accept", answer, None
            if ctx._final_continues >= ctx._final_continue_max:
                ctx.trace.event(
                    "before_final_continue_rejected",
                    mw=mw.name,
                    reason="budget_exceeded",
                    budget=ctx._final_continue_max,
                )
                return "accept", answer, None
            ctx._final_continues += 1
            ctx.trace.event(
                "before_final_continue",
                mw=mw.name,
                count=ctx._final_continues,
                feedback=feedback,
            )
            return "continue", answer, feedback

        ctx.trace.event(
            "middleware_warning",
            hook="before_final",
            mw=mw.name,
            reason=f"unknown_action: {action}",
        )

    return "accept", answer, None


async def _dispatch(name: str, args: dict, ctx: Context) -> str:
    if name not in ctx.workspace.tool_names:
        return f"Unavailable tool: {name}"
    signature = name + ":" + json.dumps(args, sort_keys=True, ensure_ascii=False, default=str)
    ctx._stall_signature_counts[signature] += 1
    ctx._last_tool_signature = signature
    if _is_introspection_tool(name, args, ctx):
        ctx._introspection_streak += 1
    else:
        ctx._introspection_streak = 0

    original_name = name
    original_args = copy.deepcopy(args)
    action = "executed"
    skipped = False
    result = ""
    result_metadata: dict = {}

    # before_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.before_tool:
            try:
                ret = await mw.before_tool(name, args, ctx)
                if isinstance(ret, dict):
                    act = ret.get("action")
                    if act == "skip":
                        if action == "redirected":
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="skip_after_redirect",
                            )
                        else:
                            result = str(ret.get("result", ""))
                            action = "skipped"
                            skipped = True
                            ctx._tool_skips += 1
                            ctx.trace.event(
                                "before_tool_skip", mw=mw.name, tool=original_name
                            )
                            break
                    elif act == "redirect":
                        new_name = ret.get("name")
                        new_args = ret.get("args")
                        if (
                            isinstance(new_name, str)
                            and new_name
                            and isinstance(new_args, dict)
                        ):
                            ctx.trace.event(
                                "before_tool_redirect",
                                mw=mw.name,
                                from_tool=original_name,
                                to_tool=new_name,
                            )
                            name, args = new_name, new_args
                            action = "redirected"
                            ctx._tool_redirects += 1
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="invalid_redirect_payload",
                            )
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason=f"unknown_action: {act}",
                        )
                elif isinstance(ret, tuple):
                    if (
                        len(ret) == 2
                        and isinstance(ret[0], str)
                        and isinstance(ret[1], dict)
                    ):
                        name, args = ret
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason="invalid_tuple_return",
                        )
                elif ret is not None:
                    ctx.trace.event(
                        "middleware_warning",
                        hook="before_tool",
                        mw=mw.name,
                        reason=f"unexpected_return_type: {type(ret).__name__}",
                    )
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="before_tool", mw=mw.name, error=str(e)
                )

    # execution (skipped if before_tool set skip)
    if not skipped:
        if name not in ctx.workspace.tool_names:
            return f"Unavailable tool: {name}"
        builtin = await _dispatch_builtin(name, args, ctx)
        if builtin is not None:
            result = builtin
        elif name in ctx.workspace.extra_tools:
            try:
                raw_result = await ctx.workspace.extra_tools[name](args, ctx)
                result, result_metadata = _normalize_tool_result(
                    raw_result, ctx, tool=name
                )
            except Exception as e:
                result = f"workspace tool {name!r} error: {e}"
        else:
            result = f"Unknown tool: {name}"

    # after_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.after_tool:
            try:
                ret = await mw.after_tool(name, args, result, ctx)
                if isinstance(ret, dict):
                    result = str(ret.get("result", result))
                    if "metadata" in ret:
                        if isinstance(ret["metadata"], dict):
                            result_metadata.update(copy.deepcopy(ret["metadata"]))
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="after_tool",
                                mw=mw.name,
                                reason="metadata_not_dict",
                            )
                    inject_list = ret.get("inject", [])
                    if inject_list:
                        inj = inject_list[0]
                        if (
                            not isinstance(inj, dict)
                            or not isinstance(inj.get("name"), str)
                            or not inj["name"]
                            or not isinstance(inj.get("args", {}), dict)
                        ):
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="malformed_payload",
                            )
                        elif ctx._in_injected_call:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="recursion_guard",
                            )
                        elif ctx._pending_injections:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="one_per_turn",
                            )
                        else:
                            inj.setdefault("args", {})
                            ctx._pending_injections.append(inj)
                            ctx.trace.event(
                                "after_tool_inject_queued", mw=mw.name, tool=inj["name"]
                            )
                elif isinstance(ret, str):
                    result = ret
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="after_tool", mw=mw.name, error=str(e)
                )

    _observe_tool_result(
        ctx,
        requested_name=original_name,
        requested_args=original_args,
        executed_name=name,
        executed_args=args,
        result=result,
        skipped=skipped,
    )

    # record ToolCallRecord (single exit point)
    ctx._tool_seq += 1
    rec = ToolCallRecord(
        seq=ctx._tool_seq,
        requested_name=original_name,
        requested_args=original_args,
        executed_name=name,
        executed_args=copy.deepcopy(args),
        turn=ctx._current_turn,
        result_preview=result[:500],
        result_metadata=copy.deepcopy(result_metadata),
        action=action,
        source="middleware_inject" if ctx._in_injected_call else "model",
    )
    ctx.tool_history.append(rec)
    ctx.current_turn_calls.append(rec)

    if (
        ctx._stall_nudges < 3
        and not ctx._stall_nudge_pending
        and (
            ctx._introspection_streak >= _STALL_INTROSPECTION_STREAK_LIMIT
            or ctx._stall_signature_counts.get(signature, 0)
            >= _STALL_SAME_SIGNATURE_LIMIT
        )
    ):
        ctx._stall_nudge_pending = _nudge_for_stall(ctx, name, args) or ""

    return result


